import type { WisdomArticle } from "./types";
import { educationImages, eduImage } from "./education-images";

/** Articles sourced verbatim from temp-content/p2.txt (link-scrubbed, headings normalized) */
export const p2Articles: WisdomArticle[] = [
  {
    id: "origins-of-jyotish",
    section: "introduction",
    title: { en: `Jyotish – Origins of Vedic Astrology`, ja: `ジョーティッシュ – ヴェーダ占星術の起源` },
    related: ["jyotish-explained","jyotish-and-karma","paradigm-shift"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Origins of Vedic Astrology`, ja: `ジョーティッシュ – ヴェーダ占星術の起源` } },
      { type: "paragraph", text: { en: `Summary: This article explores the origins of Vedic Astrology (Jyotish) and the process of Vedic cognition. It identifies the great Vedic Seer Maharishi Parashara as the ‘father of Jyotish Astrology’ and discusses his classical Jyotish text, the Brihat Parasara Hora Shastra.`, ja: `概要: この記事では、ヴェーダ占星術 (ジョーティッシュ) の起源とヴェーダ認識のプロセスを探ります。この論文では、偉大なヴェーダの聖見者マハリシ・パラシャラを「ジョーティッシュ占星術の父」と特定し、彼の古典的なジョーティッシュのテキストであるブリハット・パラサラ・ホラ・シャストラについて論じています。` } },
      { type: "heading", level: 3, text: { en: `Origins of Vedic Astrology and the Process of Vedic Cognition`, ja: `ヴェーダ占星術の起源とヴェーダ認識の過程` } },
      { type: "paragraph", text: { en: `Ask a Western Astrologer about the origins of astrology and they will usually provide a chronological account describing how the subject passed from one culture to another, moving between countries and civilizations over time. Western modes of thought are comfortable with this approach because it aligns with our sense of history. We enjoy organising the past through names, dates, timelines, and geographical locations.`, ja: `西洋占星術師に占星術の起源について尋ねると、通常、その主題が時間の経過とともに国や文明の間を移動しながら、ある文化から別の文化にどのように伝わったかを時系列で説明してくれるでしょう。西洋の思考様式は、このアプローチが私たちの歴史感覚と一致しているため、このアプローチに満足しています。私たちは、名前、日付、タイムライン、地理的な場所を通じて過去を整理することを楽しんでいます。` } },
      { type: "paragraph", text: { en: `Ask a Jyotish Astrologer the same question and the answer is likely to be that it “came from God” [1]. This is a crucial point and highlights a fundamental distinction between Jyotish and Western Astrology. According to Vedic tradition, the knowledge of Jyotish Astrology, just like the knowledge of maintaining perfect health through Ayurveda and the vast body of Vedic Science as a whole, was not invented but rather revealed or cognized.`, ja: `ジョーティッシュ占星術師に同じ質問をすると、おそらく「神から来たもの」という答えが返ってくるでしょう [1]。これは重要な点であり、ジョーティッシュ占星術と西洋占星術の根本的な違いを強調しています。ヴェーダの伝統によれば、ジョーティッシュ占星術の知識は、アーユルヴェーダやヴェーダ科学全体を通じて完全な健康を維持する知識と同様、発明されたものではなく、明らかにされたか認識されたものです。` } },
      { type: "paragraph", text: { en: `Jyotish was neither discovered nor created by human beings, nor was it gradually developed through experimentation over centuries.`, ja: `ジョーティッシュは人間によって発見または作成されたものではなく、何世紀にもわたる実験を通じて徐々に開発されたものでもありません。` } },
      { type: "paragraph", text: { en: `There are few clear equivalents within Western thought to explain the process of Vedic cognition. Perhaps the closest comparison would be moments of extraordinary artistic inspiration, creative genius, or scientific insight, where the complete understanding of a great work, invention, or theorem seems to appear in the mind instantly.`, ja: `西洋思想の中に、ヴェーダの認識プロセスを説明する明確な同等物はほとんどありません。おそらく、最も近い例は、並外れた芸術的インスピレーション、創造的な天才、または科学的洞察の瞬間であり、偉大な作品、発明、または定理の完全な理解が瞬時に頭の中に現れるように見える場合です。` } },
      { type: "heading", level: 3, text: { en: `Modern ‘Download’ Analogy to Vedic Cognition Process`, ja: `現代の「ダウンロード」をヴェーダの認知プロセスに喩える` } },
      { type: "paragraph", text: { en: `All of the great works of Vedic Science are said to have originated through revealed knowledge or cognition within the consciousness of highly evolved sages, seers, and Rishis of ancient times. These individuals devoted entire lifetimes to the practice of Yoga and meditation, enabling them to access higher states of awareness. Their level of consciousness was far beyond what most people experience in everyday life.`, ja: `ヴェーダ科学の偉大な著作はすべて、古代の高度に進化した賢者、先見者、聖師たちの意識の中に明らかにされた知識や認識を通じて生まれたと言われています。これらの人々は生涯をヨガと瞑想の実践に捧げ、より高い意識状態にアクセスできるようにしました。彼らの意識レベルは、ほとんどの人が日常生活で経験するレベルをはるかに超えていました。` } },
      { type: "paragraph", text: { en: `A useful modern analogy is the Internet. Imagine connecting a personal computer to a remote server—or even to “The Cloud”—and downloading all the information required directly into the machine. Naturally, we must know how to operate the computer correctly and possess the necessary password—perhaps comparable to using the correct Sanskrit mantras—to gain access to the information stored remotely. This analogy reflects the Vedic Model of Reality, in which the universe and all living beings are viewed as parts of an interconnected whole.`, ja: `現代で役立つ例えはインターネットです。パーソナル コンピュータをリモート サーバー (または「クラウド」) に接続し、必要なすべての情報をマシンに直接ダウンロードすることを想像してください。当然のことながら、リモートに保存されている情報にアクセスするには、コンピューターの正しい操作方法を理解し、必要なパスワード (おそらく正しいサンスクリット語のマントラを使用することに匹敵します) を所有している必要があります。このアナロジーは、宇宙とすべての生き物が相互に接続された全体の一部として見なされる、現実のヴェーダ モデルを反映しています。` } },
      { type: "paragraph", text: { en: `If we continue with this analogy, it becomes clear that the information stored on a server exists whether or not our computer, tablet, or phone can access it. The same principle applies to the knowledge of Vedic Astrology. The information within the “Cosmic Computer” is always present, waiting to be accessed. During certain ages, direct access to this knowledge may be available to a small number of enlightened individuals.`, ja: `この例えを続けると、コンピューター、タブレット、または携帯電話がアクセスできるかどうかに関係なく、サーバーに保存されている情報が存在することが明らかになります。同じ原則がヴェーダ占星術の知識にも当てはまります。 「宇宙コンピュータ」内の情報は常に存在し、アクセスされるのを待っています。特定の年齢の間は、少数の啓発された個人がこの知識に直接アクセスできる場合があります。` } },
      { type: "paragraph", text: { en: `In the current Dark Age of Kali Yuga [2], direct cognition is considered unavailable. As a result, we rely upon the cognized wisdom passed down by enlightened sages from previous ages.`, ja: `現在のカリユガの暗黒時代 [2] では、直接認識は不可能であると考えられています。その結果、私たちは前の時代から啓発された賢者たちによって伝えられた認識された知恵に依存しています。` } },
      { type: "heading", level: 3, text: { en: `Maharishi Parashara – ‘Father’ of Vedic Astrology`, ja: `マハリシ・パラシャラ – ヴェーダ占星術の「父」` } },
      { type: "paragraph", text: { en: `The Vedic Sage, or Seer, most widely regarded as the “father of Jyotish Astrology” is Maharishi Parashara (Maha meaning “great” and Rishi meaning “seer”) [3]. His Sanskrit work, the Brihat Parasara Hora Shastra [4], remains one of the most important and influential texts in Vedic Astrology.`, ja: `「ジョーティッシュ占星術の父」として最も広くみなされているヴェーダの賢者、または先見者は、マハリシ・パラシャラ（マハは「偉大な」を意味し、リシは「先見者」を意味する）です[3]。彼のサンスクリット語の著作である『ブリハット パラサラ ホラ シャストラ』 [4] は、依然としてヴェーダ占星術において最も重要かつ影響力のあるテキストの 1 つです。` } },
      eduImage(educationImages.parashara, {
        en: "Maharishi Parashara, father of Vedic astrology",
        ja: "ヴェーダ占星術の父、マハリシ・パラシャラ",
      }),
      { type: "paragraph", text: { en: `From the Vedic perspective, exactly when or where Parashara lived is of secondary importance. Even if his teachings had been lost over the course of time, it would not fundamentally matter because the knowledge was never considered to be personally his. The wisdom itself existed independently and was simply cognized through him. Future Rishis born in other ages could once again re-cognize the complete body of Jyotish Shastra and make it available for the benefit of humanity.`, ja: `ヴェーダの観点からは、パラシャラが正確にいつ、どこに住んでいたかは二番目に重要です。たとえ彼の教えが時間の経過とともに失われていたとしても、その知識は彼の個人的なものとは決して考えられなかったので、それは基本的に問題ではありません。知恵自体は独立して存在し、彼を通して認識されただけです。他の時代に生まれた将来の聖者は、ジョーティッシュ・シャストラの完全な体を再び認識し、それを人類の利益のために利用できるようにするかもしれません。` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `脚注` } },
      { type: "paragraph", text: { en: `[1] The Vedic concept of God differs significantly from the idea of a distant, judgemental deity often associated with the Abrahamic traditions. In the Vedic understanding, the all-pervading “GOD” may be viewed as a three-letter acronym representing fundamental principles of nature: G – Generator (personified as Brahma), O – Operator (personified as Vishnu), and D – Destroyer (personified as Maheshwara or Shiva). This divine reality is not something separate from us; rather, we exist within it, just as a fish exists within the ocean. Some describe it as the “field of creative intelligence.” There are also many interesting parallels between this Vedic Model of Reality and modern scientific models.`, ja: `[1] ヴェーダの神の概念は、アブラハムの伝統によく関連付けられている遠く離れた裁きの神という概念とは大きく異なります。ヴェーダの理解では、すべてに浸透している「GOD」は、自然の基本原理を表す 3 文字の頭字語と見なされます。G – 生成者 (ブラフマーとして擬人化)、O – 操作者 (ヴィシュヌとして擬人化)、D – 破壊者 (マヘシュワラまたはシヴァとして擬人化)。この神聖な現実は私たちから切り離されたものではありません。むしろ、魚が海の中に存在するのと同じように、私たちはその中に存在します。それを「創造的知性の分野」と表現する人もいます。このヴェーダの現実モデルと現代の科学モデルの間には、興味深い類似点も数多くあります。` } },
      { type: "paragraph", text: { en: `[2] Vedic literature describes four major ages, or great cycles of time, each characterised by distinct qualities. Most, though not all, scholars maintain that humanity is currently living in the age of Kali Yuga. There is ongoing debate regarding exactly when this age began—many place its commencement around 3102 BCE, following the departure of Krishna from His earthly incarnation—and how long it will continue. Some estimates suggest approximately another 17,000 years, while others propose a much longer duration. Certain scholars also suggest the existence of smaller cycles operating within the larger Yuga framework.`, ja: `[2] ヴェーダ文献には 4 つの主要な時代、または大きな時間のサイクルが記述されており、それぞれが異なる性質によって特徴付けられています。すべてではありませんが、ほとんどの学者は、人類は現在カリユガの時代に生きていると主張しています。この時代が正確にいつ始まったかについては、議論が続いている。多くの人はクリシュナが地上での転生を離れた後、紀元前 3102 年頃から始まったとしている。そして、それがいつまで続くのか。さらに約 17,000 年を示唆する推定もあれば、さらに長い期間を示唆する推定もあります。一部の学者は、より大きなユガの枠組みの中で動作する小さなサイクルの存在も示唆しています。` } },
      { type: "paragraph", text: { en: `[3] Parashara is credited with cognizing the rules, principles, and systematic framework that form the basis of Jyotish.`, ja: `[3] パラシャラは、ジョーティッシュの基礎を形成する規則、原則、体系的な枠組みを認識したと信じられています。` } },
      { type: "paragraph", text: { en: `[4] Scholars continue to debate which chapters of the currently available printed editions of the Brihat Parasara Hora Shastra can be directly attributed to Parashara and which may originate from the Sage Jaimini. Although the two systems sometimes appear to differ, it is generally accepted that Parashara’s methods are particularly suited to the present age of Kali Yuga, while Jaimini’s teachings may have been intended for a different age.`, ja: `[4] 学者たちは、ブリハット・パラシャラ・ホラ・シャーストラの現在入手可能な印刷版のどの章がパラシャラに直接帰することができ、どの章が聖者ジャイミニに由来する可能性があるかについて議論を続けています。 2 つのシステムは異なるように見えることもありますが、パラシャラのメソッドは特に現在のカリ ユガの時代に適しているのに対し、ジャイミニの教えは別の時代を対象としたものである可能性があることが一般に認められています。` } },
    ],
  },
  {
    id: "jyotish-and-karma",
    section: "introduction",
    title: { en: `Jyotish and Karma`, ja: `ジョーティッシュとカルマ` },
    related: ["three-types-karma","predictive-capabilities","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish and Karma`, ja: `ジョーティッシュとカルマ` } },
      { type: "paragraph", text: { en: `Summary: This article explores the principles of karma and reincarnation within the framework of Jyotish Astrology. It discusses the various categories of karma, explains how returning karmas can be identified, and describes how Vedic Astrology's remedial measures may help modify their effects.`, ja: `概要: この記事では、ジョーティッシュ占星術の枠組みの中でカルマと輪廻の原則を探ります。カルマのさまざまなカテゴリについて説明し、戻ってきたカルマをどのように識別できるかを説明し、ヴェーダ占星術の救済措置がその影響を修正するのにどのように役立つかを説明します。` } },
      { type: "heading", level: 3, text: { en: `Vedic Astrology, Karma and Reincarnation`, ja: `ヴェーダ占星術、カルマ、輪廻転生` } },
      { type: "paragraph", text: { en: `In the West, the words kama and karma are often confused and sometimes mispronounced. Kama refers to desire, and many people are familiar with the Kama Sutra. Karma, on the other hand, literally means action. Since actions are constantly taking place, karma is continually being generated throughout the world.`, ja: `西洋では、カーマとカルマという言葉はしばしば混同され、時々誤って発音されます。カーマとは欲望を意味し、カーマスートラは多くの人に親しまれています。一方、カルマは文字通り行為を意味します。行為は常に行われているため、世界中でカルマが生成され続けています。` } },
      { type: "paragraph", text: { en: `The concept of karma carries many subtle meanings and layers of interpretation. On an individual level, karma is generally understood as the returning consequences of our past actions—summed up by the phrase, "as you sow, so shall you reap." Within the Vedic tradition, karma can extend across multiple incarnations. Karma is also closely connected with the concept of samskara (or sanskara)—the deep-rooted impressions and latent desires within the mind that motivate us to perform particular actions [1].`, ja: `カルマの概念には、多くの微妙な意味と解釈の層があります。個人レベルでは、カルマは一般に、私たちの過去の行為の結果として理解されており、「蒔いた種を刈り取ることになる」という言葉に要約されます。ヴェーダの伝統では、カルマは複数の転生にまたがって広がる可能性があります。カルマはまた、サムスカーラ (またはサンスカーラ) の概念、つまり特定の行動を実行する動機となる心の中に根深い印象や潜在的な願望と密接に関係しています [1]。` } },
      { type: "paragraph", text: { en: `According to Vedic Astrology, the soul (for want of a better term in the English language) does not take birth randomly. Vedic Masters teach that it incarnates into a human body—primarily—with specific physical traits determined by previous karmas. The family into which one is born, its social standing, and even the country of birth are likewise influenced by past karmic actions.`, ja: `ヴェーダ占星術によれば、魂（英語でより適切な言葉が見つかりませんが）はランダムに誕生するものではありません。ヴェーダのマスターは、それは主に過去のカルマによって決定された特定の身体的特徴を持って人間の体に転生すると教えています。人が生まれた家族、社会的地位、さらには生まれた国も同様に、過去のカルマ行為の影響を受けます。` } },
      { type: "paragraph", text: { en: `Vedic Astrology further teaches that we are not victims of our birth chart or the planetary combinations contained within it. The planets cannot be blamed for our present circumstances or challenges. Whatever we are experiencing today, whether perceived as favourable or unfavourable, is simply the manifestation of returning karmas. The planets indicate these karmas, but they do not create them.`, ja: `ヴェーダ占星術はさらに、私たちは出生図やそこに含まれる惑星の組み合わせの犠牲者ではないことを教えています。私たちの現在の状況や課題を惑星のせいにすることはできません。私たちが今日経験していることは、それが好ましいものであるか、好ましくないものであるかにかかわらず、カルマの戻りの現れにすぎません。惑星はこれらのカルマを示しますが、それらを生み出すわけではありません。` } },
      { type: "paragraph", text: { en: `In Jyotish, the planets are often described as the "Cosmic Postman." During this lifetime, they deliver some of the consequences of actions carried over from previous incarnations. We tend to label these karmas as "positive" when they bring growth, happiness, or success, and "negative" when they result in obstacles or difficulties [2]. Yet these labels are largely subjective. From a higher level of consciousness, the distinction between positive and negative karma disappears—things simply are as they are.`, ja: `ジョーティッシュでは、惑星はしばしば「宇宙の郵便配達員」として描写されます。この生涯の間に、彼らは前の転生から引き継がれた行為の結果の一部をもたらします。私たちは、これらのカルマが成長、幸福、成功をもたらす場合には「ポジティブ」とラベル付けし、障害や困難をもたらす場合には「ネガティブ」とラベル付けする傾向があります[2]。しかし、これらのラベルは主に主観的なものです。より高い意識レベルからは、ポジティブなカルマとネガティブなカルマの区別はなくなり、物事は単にありのままになります。` } },
      { type: "paragraph", text: { en: `A self-realized Vedic Master was once asked about free will and destiny. He replied that life consists of a combination of both. As an example, he explained that our height is largely predetermined, whereas our weight is influenced by our choices and actions. The audience immediately understood the point and laughed.`, ja: `自己を実現したヴェーダのマスターは、かつて自由意志と運命について尋ねられました。彼は、人生は両方の組み合わせで構成されていると答えました。一例として、私たちの身長はほぼ決まっているのに対し、体重は私たちの選択や行動によって影響を受けると彼は説明しました。聴衆はすぐに要点を理解し、笑いました。` } },
      { type: "paragraph", text: { en: `In everyday life, many of our actions are karmically neutral. Following a reasonably vegetarian lifestyle is often said to support this balance.`, ja: `日常生活では、私たちの行動の多くはカルマ的に中立です。適度にベジタリアンのライフスタイルに従うことが、このバランスをサポートするとよく言われます。` } },
      { type: "paragraph", text: { en: `Not only do our actions matter, but so do the intentions behind them. Through regular meditation and spiritual practices, our intentions become more aligned with evolution and natural growth, rather than being driven solely by impressions and tendencies carried over from previous lifetimes.`, ja: `私たちの行動が重要であるだけでなく、その背後にある意図も重要です。定期的な瞑想やスピリチュアルな実践を通じて、私たちの意図は前世から引き継がれた印象や傾向だけによって動かされるのではなく、進化や自然な成長とより一致するようになります。` } },
      { type: "heading", level: 3, text: { en: `Prediction and ‘Prevention’ in Jyotish`, ja: `ジョーティッシュ語の予測と「予防」` } },
      { type: "paragraph", text: { en: `Jyotish enables us to both identify and redirect returning karmas. In this sense, it can truly be viewed as the ultimate Karmic Engineering System.`, ja: `Jyotish を使用すると、戻ってくるカルマを特定し、リダイレクトすることができます。この意味で、それはまさに究極のカルマ工学システムとみなすことができます。` } },
      { type: "heading", level: 3, text: { en: `1. Detecting Returning Karmas in Vedic Astrology`, ja: `1. ヴェーダ占星術で戻ってくるカルマを検出する` } },
      { type: "paragraph", text: { en: `The major karmic influences and significant events likely to arise during an individual's current incarnation can be predicted through Jyotish. This involves interpreting the "code" contained within the planetary arrangements present at the moment of birth. Just as DNA contains the information that shapes human physiology, the planetary configuration at birth contains the code that reflects returning karmas [3].`, ja: `個人の現在の転生中に起こる可能性のある主要なカルマ的影響と重大な出来事は、ジョーティッシュを通じて予測できます。これには、誕生の瞬間に存在する惑星配置に含まれる「コード」を解釈することが含まれます。 DNA に人間の生理機能を形作る情報が含まれているのと同じように、出生時の惑星の配置には、戻ってくるカルマを反映するコードが含まれています [3]。` } },
      { type: "paragraph", text: { en: `Predictions can be made across all major areas of life, including Artha, Dharma, Kama, and Moksha.`, ja: `予測は、アルタ、ダルマ、カーマ、モクシャなど、人生の主要な領域すべてにわたって行うことができます。` } },
      { type: "paragraph", text: { en: `Artha encompasses wealth in its broadest sense—financial prosperity, children, knowledge, food, health, and other forms of abundance.`, ja: `アルタには、経済的繁栄、子供、知識、食べ物、健康、その他の形の豊かさなど、最も広い意味での富が含まれます。` } },
      { type: "paragraph", text: { en: `Dharma relates to duty, character, righteous action, and activities that support evolution and natural law, including one's career path and life purpose.`, ja: `ダルマは義務、性格、正義の行動、そして進化と自然法を支える活動（キャリアパスや人生の目的を含む）に関連しています。` } },
      { type: "paragraph", text: { en: `Kama refers to desire and therefore includes relationships, pleasures of the senses, aspirations, and worldly enjoyments.`, ja: `カーマは欲望を指し、したがって人間関係、感覚の喜び、願望、世俗的な楽しみが含まれます。` } },
      { type: "paragraph", text: { en: `Moksha concerns spiritual development, personal growth, and the journey toward Self-realization.`, ja: `モクシャは、精神的な発達、個人の成長、自己実現への旅に関係しています。` } },
      { type: "paragraph", text: { en: `Jyotish can also indicate when these karmic influences are likely to manifest. This is achieved through the unique Maha Dasa system of Vedic Astrology [4], which is based on the Moon's position in the Nakshatras (constellations) at the time of birth.`, ja: `ジョーティッシュは、これらのカルマ的影響がいつ現れる可能性があるかを示すこともできます。これは、出生時のナクシャトラ (星座) における月の位置に基づいた、ヴェーダ占星術の独自のマハ ダサ システム [4] によって実現されます。` } },
      { type: "heading", level: 3, text: { en: `2. Deflecting Returning Karmas in Vedic Astrology`, ja: `2. ヴェーダ占星術で戻ってくるカルマをそらす` } },
      { type: "paragraph", text: { en: `The Vedic tradition promotes a life that is healthy, happy, and fulfilling. Consequently, Vedic Astrology contains a wide range of remedial measures intended to significantly reduce the impact of returning negative karmas. These remedies help restore balance, harmony, and well-being.`, ja: `ヴェーダの伝統は、健康で幸せで充実した生活を促進します。その結果、ヴェーダ占星術には、ネガティブなカルマの帰還による影響を大幅に軽減することを目的とした幅広い救済措置が含まれています。これらの治療法は、バランス、調和、幸福を回復するのに役立ちます。` } },
      { type: "paragraph", text: { en: `Their effectiveness is based on the understanding that we are all part of an interconnected whole. By participating in Vedic ceremonies such as Yagnas, Yagyas, or Homas, performing prescribed acts of charity, reciting specific Sanskrit mantras, or wearing suitable gemstones, it is believed that returning karmas can be modified or deflected to a considerable degree.`, ja: `それらの有効性は、私たち全員が相互に接続された全体の一部であるという理解に基づいています。ヤグナス、ヤギャ、ホーマなどのヴェーダの儀式に参加したり、所定の慈善行為を行ったり、特定のサンスクリット語のマントラを暗唱したり、適切な宝石を身に着けたりすることによって、戻ってきたカルマをかなりの程度修正または偏向できると考えられています。` } },
      { type: "paragraph", text: { en: `As a result, an individual may not need to experience the full karmic consequences during the present lifetime. At the same time, Jyotish remedies can strengthen the beneficial effects of positive karmas. For this reason, Jyotish may rightly be considered the ultimate Karmic Engineering System.`, ja: `その結果、人は今生でカルマの結果をすべて経験する必要がないかもしれません。同時に、ジョーティッシュの治療法は、ポジティブなカルマの有益な効果を強化することができます。このため、ジョーティッシュは究極のカルマ工学システムであると考えるのが当然かもしれません。` } },
      { type: "heading", level: 3, text: { en: `3. Spiritual Practices Deflect Negative Karma`, ja: `3. スピリチュアルな実践はネガティブなカルマをそらす` } },
      { type: "paragraph", text: { en: `Returning karmas can also be profoundly influenced by the spiritual practices we undertake during this lifetime.`, ja: `カルマの返却は、私たちがこの生涯で行うスピリチュアルな実践にも大きく影響される可能性があります。` } },
      { type: "paragraph", text: { en: `Most experienced Jyotish astrologers will agree that regular meditation and sadhana (spiritual practice) noticeably reduce the predicted effects of difficult karmas. Many spiritual Masters have taught that destiny itself can be transformed through daily meditation, chanting, pranayama, and related disciplines.`, ja: `ほとんどの経験豊富なジョーティッシュ占星術師は、定期的な瞑想とサーダナ (霊性修行) が、予測される困難なカルマの影響を著しく軽減することに同意するでしょう。多くのスピリチュアルなマスターは、毎日の瞑想、詠唱、プラーナヤーマ、および関連する修行を通じて運命そのものを変えることができると教えてきました。` } },
      { type: "paragraph", text: { en: `The great Spiritual Master Paramahansa Yogananda [5] affirmed this principle when he stated that as an individual moves "into the orbit of the Divine, they move out of the orbit of planetary influences."`, ja: `偉大なスピリチュアルマスター、パラマハンサ・ヨガナンダ[5]は、個人が「神の軌道に入るにつれて、惑星の影響の軌道から外に出る」と述べ、この原則を肯定しました。` } },
      { type: "paragraph", text: { en: `Those fortunate enough to have a Self-realized Spiritual Master (Guru) should also recognize the power of the Guru's Grace, which can remove major obstacles and greatly lessen the impact of returning negative karmas.`, ja: `自己実現したスピリチュアルマスター（グル）を持つ幸運な人々は、大きな障害を取り除き、ネガティブなカルマを返すことによる影響を大幅に軽減できるグルの恩寵の力も認識すべきです。` } },
    ],
  },
  {
    id: "three-types-karma",
    section: "introduction",
    title: { en: `Three Types of Karma – Sanchita, Prarabdha and Agami`, ja: `3 種類のカルマ – サンチタ、プララブダ、アガミ` },
    related: ["jyotish-and-karma","mahadashas","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Three Types of Karma – Sanchita, Prarabdha and Agami`, ja: `3 種類のカルマ – サンチタ、プララブダ、アガミ` } },
      { type: "paragraph", text: { en: `The Vedas clearly describe three primary categories of karma: Sanchita, Prarabdha, and Agami. Jyotish Astrology is primarily concerned with the Prarabdha aspect of karma [6]. However, when Self-realization is attained, all karmas associated with previous lives are transcended.`, ja: `ヴェーダには、カルマの 3 つの主要なカテゴリ、サンチタ、プララブダ、アガミが明確に説明されています。ジョーティッシュ占星術は主にカルマのプララブダの側面に関係しています [6]。しかし、自己実現が達成されると、前世に関連したすべてのカルマが超越されます。` } },
      { type: "paragraph", text: { en: `On a personal note: I have complete confidence in the effectiveness of Jyotish remedial measures for reducing suffering in this lifetime. Nevertheless, certain questions remain. Are we genuinely reducing karmas, or merely postponing them to a future incarnation? Can karma truly be modified in this way? Or does an individual possess sufficient positive karma within their karmic "storehouse"—their own karmic credit account—to encounter a Jyotish astrologer and receive guidance regarding these remedies in the first place? Such questions are perhaps best answered by an enlightened Master.`, ja: `個人的なメモですが、私はこの世での苦しみを軽減するためのジョーティッシュの救済措置の有効性に完全な自信を持っています。それにもかかわらず、いくつかの疑問が残ります。私たちは本当にカルマを減らしているのでしょうか、それとも単にカルマを将来の転生に延期しているだけなのでしょうか？カルマは本当にこのように修正できるのでしょうか?それとも、個人は、そもそもジョーティッシュ占星術師に会い、これらの治療法に関する指導を受けるのに十分な、カルマの「倉庫」、つまり自分自身のカルマ信用口座の中に十分なポジティブなカルマを持っているのでしょうか？このような質問には、おそらく啓発されたマスターが最もよく答えてくれます。` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `脚注` } },
      { type: "heading", level: 3, text: { en: `[1]`, ja: `[1]` } },
      { type: "paragraph", text: { en: `Samskaras are deep-rooted impressions and desires left within the mind by past actions, including those from previous lifetimes. In the Vedic understanding, the mind is not confined to the brain; rather, it extends beyond and surrounds the body. One Vedic pundit described these latent impressions as "post-it notes attached to the soul."`, ja: `サムスカーラとは、前世を含む過去の行為によって心の中に残された根深い印象や願望です。ヴェーダの理解では、心は脳に限定されません。むしろ、それは身体を超えて広がり、身体を取り囲んでいます。あるヴェーダの専門家は、これらの潜在的な印象を「魂に貼り付けられた付箋」と表現しました。` } },
      { type: "paragraph", text: { en: `Karma is frequently illustrated as a wheel. Latent impressions in the mind generate actions, those actions create new impressions, and future actions are then influenced by those impressions. The process continues cyclically. Through meditation and spiritual practices, however, this cycle can be broken. Karma and samskara are therefore inseparably connected.`, ja: `カルマは車輪として描かれることがよくあります。心の潜在的な印象が行動を生み出し、その行動が新たな印象を生み出し、その後の行動はその印象に影響を受けます。このプロセスは周期的に継続します。しかし、瞑想やスピリチュアルな実践を通じて、このサイクルを断ち切ることができます。したがって、カルマとサムスカーラは切り離せない関係にあります。` } },
      { type: "heading", level: 3, text: { en: `[2]`, ja: `[2]` } },
      { type: "paragraph", text: { en: `What creates negative karma? One Vedic scholar explained it simply: "doing to others what we would not wish done to ourselves." This principle may reasonably be extended to our treatment of all living beings and the natural environment.`, ja: `何がマイナスのカルマを生み出すのでしょうか？あるヴェーダ学者はそれを簡単に説明しました、「自分にしてほしくないことを他人にすること」です。この原則は、すべての生き物と自然環境の扱いにも合理的に拡張できます。` } },
      { type: "heading", level: 3, text: { en: `[3]`, ja: `[3]` } },
      { type: "paragraph", text: { en: `Karmic influences affecting every aspect of life are interpreted in Vedic Astrology through the positions of the nine planets within the twelve zodiac signs, twelve houses, and twenty-seven Nakshatras, as shown in a person's birth chart calculated using the sidereal zodiac.`, ja: `人生のあらゆる側面に影響を与えるカルマの影響は、恒星黄道帯を使用して計算された人の出生図に示されるように、ヴェーダ占星術では、12 の星座、12 ハウス、27 のナクシャトラ内の 9 つの惑星の位置を通じて解釈されます。` } },
      { type: "heading", level: 3, text: { en: `[4]`, ja: `[4]` } },
      { type: "paragraph", text: { en: `The timing of karmic influences that are likely to become prominent in life is calculated through the Vimsottari Maha Dasha system, based on the natal position of the Moon within one of the twenty-seven Nakshatras.`, ja: `人生において顕著になる可能性のあるカルマ的影響のタイミングは、27 のナクシャトラの 1 つにおける月の出生位置に基づいて、ヴィムショッタリ マハ ダシャ システムを通じて計算されます。` } },
      { type: "heading", level: 3, text: { en: `[5]`, ja: `[5]` } },
      { type: "paragraph", text: { en: `Paramahansa Yogananda (1893–1952) was a Self-realized sage who spent a significant portion of his life in the West teaching yoga and Vedic philosophy. His most widely read and highly recommended work is the Autobiography of a Yogi, published by the Yogoda Satsanga Society of India.`, ja: `パラマハンサ ヨガナンダ (1893 ～ 1952 年) は、人生のかなりの部分を西洋で過ごし、ヨガとヴェーダ哲学を教えた自己実現の聖者でした。彼の最も広く読まれ、強く推奨されている著書は、インドのヨゴダ・サットサンガ協会から出版された『あるヨギの自伝』です。` } },
      { type: "paragraph", text: { en: `2013 Edition: ISBN-10: 818953551X`, ja: `2013 年版: ISBN-10: 818953551X` } },
      { type: "paragraph", text: { en: `ISBN-13: 978-8189535513`, ja: `ISBN-13: 978-8189535513` } },
      { type: "heading", level: 3, text: { en: `[6]`, ja: `[6]` } },
      { type: "heading", level: 3, text: { en: `Categories of Karma`, ja: `カルマのカテゴリー` } },
      { type: "paragraph", text: { en: `• Sanchita – The accumulated storehouse of all karmas from previous births.`, ja: `• サンチタ – 前世からのすべてのカルマが蓄積された倉庫。` } },
      { type: "paragraph", text: { en: `• Prarabdha – The portion of Sanchita karma that must be experienced and worked through in the current lifetime. It is often said that Prarabdha karma is best suited to support our evolutionary growth in this incarnation.`, ja: `• プララブダ – サンチタ カルマのうち、今生で経験し、乗り越えなければならない部分。プララブダのカルマは、この転生における私たちの進化的成長をサポートするのに最も適しているとよく言われます。` } },
      { type: "paragraph", text: { en: `• Agami – The new karma generated in this lifetime that will be carried forward into future incarnations.`, ja: `• アガミ – この生涯で生成され、将来の転生に引き継がれる新しいカルマ。` } },
      { type: "paragraph", text: { en: `Jyotish – Sidereal Zodiac`, ja: `ジョーティッシュ – 恒星黄道帯` } },
      { type: "paragraph", text: { en: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac, thereby addressing one of the main objections astronomers raise against astrology. The article also illustrates how Sun signs, Ascendants, and planetary positions can appear in different zodiac signs when calculated using these two systems.`, ja: `概要: この記事では、ヴェーダ占星術と西洋占星術で使用される黄道帯の違いについて説明します。これは、ジョーティッシュが移動可能な熱帯黄道帯ではなく、固定された恒星黄道帯に依存している理由を説明し、それによって天文学者が占星術に対して提起する主な反対の 1 つに対処します。この記事では、これら 2 つのシステムを使用して計算した場合に、太陽星座、アセンダント、惑星の位置がさまざまな星座でどのように表示されるかについても説明します。` } },
      { type: "heading", level: 3, text: { en: `Jyotish Uses the Fixed Sidereal Zodiac`, ja: `ジョーティッシュは固定恒星黄道帯を使用します` } },
      { type: "paragraph", text: { en: `Jyotish Astrology employs a different zodiac system from the one commonly used in Western Astrology.`, ja: `ジョーティッシュ占星術は、西洋占星術で一般的に使用されているものとは異なる黄道帯システムを採用しています。` } },
      { type: "paragraph", text: { en: `Both Jyotish and Western Astrology are based on an imaginary celestial sphere surrounding the Earth. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. The same zodiac sign names—Aries, Taurus, Gemini, and so on—are used in both traditions. The Sun appears to move through each zodiac sign in approximately one month.`, ja: `ジョーティッシュ占星術と西洋占星術はどちらも、地球を取り囲む想像上の天球に基づいています。各システムでは、この球は、オレンジのセグメントとよく似た、それぞれ 30 度の 12 の等しいセクションに分割されます。どちらの伝統でも、同じ星座の名前 (牡羊座、牡牛座、双子座など) が使用されています。太陽は約 1 か月かけて各星座を移動するように見えます。` } },
      { type: "paragraph", text: { en: `Jyotish uses the fixed, or Sidereal Zodiac. The term sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently fixed using the background of the seemingly non-moving stars within our galaxy as a reference [1]. As a result, the zodiac signs remain consistently aligned with the stellar constellations. The beginning of the first sign, Aries, therefore remains fixed in Vedic Astrology, and all the other zodiac signs maintain their permanent relationship to the distant background stars.`, ja: `Jyotish は固定黄道帯、つまり恒星黄道帯を使用します。恒星という用語は「星に関して」を意味します。恒星黄道帯の開始点は、銀河内の一見動かない星の背景を参照として使用して永続的に固定されます [1]。その結果、黄道十二宮は常に星座と一致した状態を保ちます。したがって、最初の星座の始まりである牡羊座はヴェーダ占星術では固定されたままであり、他のすべての星座は遠くの背景の星との永続的な関係を維持します。` } },
      { type: "paragraph", text: { en: `Western Astrology, by contrast, uses the Tropical Zodiac, which is movable. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is tied to the position of the equinox. This movement occurs due to the astronomically observed phenomenon known as the precession of the equinoxes [2].`, ja: `対照的に、西洋占星術では、移動可能なトロピカル ゾディアックが使用されます。この黄道帯の開始点は、春分点の位置に関連付けられているため、恒星の背景に対して徐々に移動します。この動きは、春分点の歳差運動として知られる天文学的に観察される現象によって発生します [2]。` } },
      { type: "paragraph", text: { en: `Consequently, in Western Astrology the sign referred to as Aries slowly changes its position in the sky relative to the fixed stars over long periods of time. It is not permanently connected to a specific stellar constellation. Many people, including students of Western Astrology, find this fact quite surprising when they first encounter it.`, ja: `その結果、西洋占星術では牡羊座と呼ばれる星座は、長い時間をかけて恒星に対する空の位置をゆっくりと変化させます。 It is not permanently connected to a specific stellar constellation.西洋占星術の学生を含む多くの人は、この事実に初めて遭遇すると、非常に驚​​くべきことに気づきます。` } },
      { type: "paragraph", text: { en: `Astronomers frequently criticize Western Astrology because the Tropical Zodiac moves relative to the fixed stars. Since the position of Aries gradually shifts over time, they question the validity of associating it with a fixed area of the sky. However, this criticism does not apply to Jyotish because it uses a fixed Sidereal Zodiac rather than a movable one.`, ja: `天文学者は、熱帯黄道帯が恒星に対して相対的に移動するため、西洋占星術を頻繁に批判します。牡羊座の位置は時間の経過とともに徐々に変化するため、牡羊座を空の固定領域と関連付けることの妥当性を疑問視しています。ただし、ジョーティッシュでは可動黄道帯ではなく固定恒星黄道帯が使用されているため、この批判は当てはまりません。` } },
      { type: "heading", level: 3, text: { en: `Ayanamsa – Angular Difference Between the Two Zodiacs`, ja: `アヤナムサ – 2 つの黄道帯の角度の違い` } },
      { type: "paragraph", text: { en: `The angular separation between the Sidereal and Tropical zodiacs is known as the ayanamsa (ayanāṃśa or ayanamsha), and this difference increases gradually over time [3]. Although both zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used by Western astrologers has since shifted away from that original position.`, ja: `恒星黄道帯と熱帯黄道帯の間の角度の分離はアヤナムサ (ayanāṃśa または ayanamsha) として知られており、この差は時間の経過とともに徐々に増加します [3]。両方の黄道帯は約 1,700 年前にはほぼ一直線上にありましたが、西洋占星術師が使用した熱帯黄道帯はそれ以来、元の位置からずれています。` } },
      { type: "paragraph", text: { en: `As of 2021, the difference between the two zodiacs is approximately 24 degrees. Therefore, if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will be located at approximately 29° – 24° = 5° Virgo in the Sidereal Zodiac. In this example, the Sun remains in Virgo in both systems.`, ja: `2021 年の時点で、2 つの星座の差は約 24 度です。したがって、太陽が熱帯黄道帯の乙女座 29 度に位置する場合、恒星黄道帯では約 29 度 – 24 度 = 5 度の乙女座に位置することになります。この例では、太陽はどちらの星系でも乙女座に留まります。` } },
      { type: "paragraph", text: { en: `However, if the Sun lies between 0° and 24° Virgo in the Tropical Zodiac, it will fall into Leo in the Sidereal Zodiac used by Vedic Astrology. In other words, it moves backwards (anti-clockwise) by the amount of the ayanamsa—around 24 degrees—and enters the previous sign [4].`, ja: `ただし、太陽が熱帯黄道帯の乙女座0°と24°の間にある場合、ヴェーダ占星術で使用される恒星黄道帯では太陽は獅子座に該当します。言い換えれば、アヤナムサの量だけ後方 (反時計回り) に移動し (約 24 度)、前のサインに入ります [4]。` } },
      { type: "paragraph", text: { en: `This means that a person's Sun sign may differ between the two systems. Someone considered a Virgo in Western Astrology may actually be a Leo according to Jyotish. The same principle applies not only to the Sun but also to all planetary positions and the Ascendant. These sign differences can help explain many of the inconsistencies and anomalies encountered when charts are interpreted solely through modern Western Astrology.`, ja: `これは、人の太陽星座が 2 つのシステム間で異なる可能性があることを意味します。西洋占星術で乙女座と考えられている人は、ジョーティッシュによれば、実際には獅子座である可能性があります。同じ原理が太陽だけでなく、すべての惑星の位置とアセンダントにも当てはまります。これらのサインの違いは、現代の西洋占星術だけでチャートを解釈したときに遭遇する矛盾や異常の多くを説明するのに役立ちます。` } },
    ],
  },
  {
    id: "nakshatras-stellar-1",
    section: "nakshatras",
    title: { en: `Nakshatras – Stellar Constellations`, ja: `ナクシャトラ – 恒星星座` },
    related: ["nakshatras-human-physiology","sidereal-zodiac-p3","mahadashas"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Nakshatras – Stellar Constellations`, ja: `ナクシャトラ – 恒星星座` } },
      { type: "paragraph", text: { en: `Jyotish places considerable importance on the stellar constellations known as Nakshatras. They play a vital role in chart interpretation, compatibility analysis, and determining favourable timings for important activities through Muhurtha.`, ja: `ジョーティッシュは、ナクシャトラとして知られる恒星の星座を非常に重視しています。彼らは、チャートの解釈、互換性分析、およびムハルタを通じて重要な活動に有利なタイミングを決定する上で重要な役割を果たします。` } },
      { type: "paragraph", text: { en: `There are 27 Nakshatras, often referred to as Lunar Mansions, distributed evenly throughout the sky. Technically speaking, they are arranged as equal sectors along the ecliptic.`, ja: `しばしば月の邸宅と呼ばれる 27 のナクシャトラが空全体に均等に分布しています。技術的に言えば、それらは黄道に沿って等しいセクターとして配置されます。` } },
      { type: "paragraph", text: { en: `Given the significance of the Nakshatras within Vedic Astrology, it is hardly surprising that Jyotish employs a zodiac system that remains permanently anchored to the fixed stars and therefore remains aligned with the Nakshatras themselves.`, ja: `ヴェーダ占星術におけるナクシャトラの重要性を考えると、ジョーティッシュが永久に恒星に固定されたままであり、したがってナクシャトラ自体と一致し続ける黄道十二宮システムを採用していることは驚くべきことではありません。` } },
      eduImage(educationImages.nakshatrasStellar, {
        en: "Nakshatras — stellar constellations",
        ja: "ナクシャトラ — 恒星星座",
      }),
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `脚注` } },
      { type: "heading", level: 3, text: { en: `[1]`, ja: `[1]` } },
      { type: "paragraph", text: { en: `The "fixed stars" are located so far from Earth that their angular movement relative to our Sun is extremely small, even across many thousands of years. For practical purposes, it is therefore reasonable to describe them as fixed or immovable.`, ja: `「恒星」は地球から非常に遠くに位置しているため、太陽に対するそれらの角の動きは、何千年にわたっても非常に小さいです。したがって、実際的な目的では、それらを固定または不動として説明するのが合理的です。` } },
      { type: "heading", level: 3, text: { en: `[2]`, ja: `[2]` } },
      { type: "paragraph", text: { en: `The equinox point on Earth's orbit around the Sun gradually shifts relative to the background of the fixed stars due to a phenomenon known as the precession of the equinoxes. This well-established astronomical effect results from a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. Earth takes approximately 26,000 years to complete one full precessional cycle.`, ja: `太陽の周りの地球の軌道上の春分点は、春分点の歳差運動として知られる現象により、恒星の背景に対して徐々に移動します。この確立された天文効果は、地球の回転軸のわずかなぐらつきによって生じます。これは、軸がゆっくりと円錐形の軌道を描くコマの動きに似ています。地球が完全な歳差運動サイクルを完了するには約 26,000 年かかります。` } },
      { type: "heading", level: 3, text: { en: `[3]`, ja: `[3]` } },
      { type: "paragraph", text: { en: `As of 2021, the angular difference between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, or one very close to it, was derived by Lahiri and is widely accepted among Jyotish astrologers. Most modern astrological tables therefore use Lahiri's ayanamsa.`, ja: `2021 年の時点で、熱帯黄道帯と恒星黄道帯の角度の差は約 24 度です。この値、またはそれに非常に近い値はラヒリによって導出され、ジョーティッシュ占星術家の間で広く受け入れられています。したがって、現代の占星術表のほとんどはラヒリのアヤナムサを使用しています。` } },
      { type: "paragraph", text: { en: `The Tropical Zodiac moves relative to the Sidereal (fixed) Zodiac at a rate of approximately one degree every 71 years. Although this shift may appear small, it was observed by ancient Egyptian astronomers thousands of years ago. Over long periods, the accumulated effect becomes highly significant.`, ja: `熱帯黄道帯は、恒星（固定）黄道帯に対して 71 年ごとに約 1 度の割合で移動します。この変化は小さいように見えるかもしれませんが、数千年前に古代エジプトの天文学者によって観察されました。長期間にわたって蓄積された効果は非常に重要になります。` } },
      { type: "heading", level: 3, text: { en: `[4]`, ja: `[4]` } },
      { type: "paragraph", text: { en: `The difference in planetary positions between the two zodiac systems is currently about 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, its Sidereal position would be calculated as:`, ja: `2 つの黄道帯システム間の惑星の位置の差は現在約 24 度です。たとえば、西洋占星術で太陽が乙女座 14 度に位置する場合、その恒星位置は次のように計算されます。` } },
      { type: "paragraph", text: { en: `14° – 24° = –10° Virgo`, ja: `14° – 24° = –10° 乙女座` } },
      { type: "paragraph", text: { en: `This indicates that the Sun is actually 10 degrees before the start of Virgo. In practical terms, it has moved backwards (anti-clockwise) into the previous sign, Leo, where its position becomes 20 degrees Leo (since –10 + 30 = 20).`, ja: `これは、太陽が実際には乙女座の開始の10度前にあることを示しています。実際には、前の星座である獅子座まで後方 (反時計回り) に移動し、その位置は獅子座 20 度になります (-10 + 30 = 20 であるため)。` } },
      { type: "paragraph", text: { en: `By contrast, if the Sun is located at 28 degrees Virgo in the Tropical Zodiac, the calculation becomes:`, ja: `対照的に、太陽が熱帯黄道帯の乙女座 28 度に位置する場合、計算は次のようになります。` } },
      { type: "paragraph", text: { en: `28° – 24° = 4° Virgo`, ja: `28° – 24° = 4° 乙女座` } },
      { type: "paragraph", text: { en: `Although the Sun has still shifted backwards by the ayanamsa amount, it remains within Virgo and therefore does not change signs.`, ja: `太陽は依然としてアヤナムサ量だけ後方に移動していますが、乙女座内に留まっているため、星座は変わりません。` } },
    ],
  },
  {
    id: "nakshatras-human-physiology",
    section: "nakshatras",
    title: { en: `The 27 Nakshatras in Human Physiology`, ja: `人体における27ナクシャトラ` },
    related: ["nakshatras-stellar-1","sidereal-zodiac-p3","twelve-houses"],
    blocks: [
      { type: "heading", level: 2, text: { en: `The 27 Nakshatras in Human Physiology`, ja: `人体における27ナクシャトラ` } },
      { type: "heading", level: 3, text: { en: `Understanding the 27 Nakshatras and Their Correspondence in the Human Body`, ja: `27ナクシャトラと人体の対応を理解する` } },
      { type: "paragraph", text: { en: `Think of the 27 Nakshatras (lunar constellations in Vedic astrology) as a network of specialized control centers in the brain — almost like a set of switches that manage how we stay alert, fall asleep, and dream. Each of these 27 groups helps regulate our body's automatic responses, like reflexes, breathing, heartbeat, and even how we experience and process pain. Interestingly, modern science shows there are also 27 corresponding groups of brain cells (neurons) that closely match the Nakshatras — not just in number, but also in their basic structure and the roles they play. This suggests a fascinating overlap between ancient astrological wisdom and modern neuroscience.`, ja: `27のナクシャトラ（ヴェーダ占星術における月の星座）を、脳内の専門的な制御中枢のネットワーク — 覚醒、睡眠、夢を司るスイッチの集合体のようなもの — と考えてみてください。これら27のグループはそれぞれ、反射、呼吸、心拍、さらには痛みの感じ方や処理の仕方など、身体の自動反応を調節する役割を担います。興味深いことに、現代科学でもナクシャトラと密接に対応する27の脳細胞（ニューロン）群が存在することが示されており、数だけでなく基本的な構造と機能の面でも一致しています。これは、古代の占星術的知恵と現代の神経科学との間に、魅力的な重なりがあることを示唆しています。` } },
      eduImage(educationImages.nakshatraWheel, {
        en: "The 27 nakshatras and zodiac signs in Jyotish",
        ja: "ジョーティッシュにおける27ナクシャトラと黄道十二宮",
      }),
      { type: "paragraph", text: { en: `When a baby is born, everything changes instantly. Inside the womb, the baby didn't need to worry about breathing on its own, eating, or keeping its body warm — the mother's body took care of all of that. But the moment of birth flips a switch: suddenly, the newborn has to independently manage all these basic survival functions. This massive shift is guided largely by a part of the brain called the hypothalamus, which in Vedic astrology is symbolically linked to the Moon. The hypothalamus works together with brainstem centers (linked to the Nakshatras) to help the baby adapt to this brand-new environment outside the womb.`, ja: `赤ちゃんが生まれると、すべてが一瞬にして変わります。子宮の中では、自分で呼吸したり、食べたり、体温を保ったりする必要はありませんでした — すべて母親の身体が担っていたからです。しかし誕生の瞬間にスイッチが切り替わり、新生児はこれらの基本的な生存機能を自ら管理しなければなりません。この大きな転換は、主に視床下部と呼ばれる脳の部位によって導かれます。ヴェーダ占星術では、視床下部は象徴的に月と結びつけられています。視床下部は、脳幹の中枢（ナクシャトラと結びつく）と協働し、赤ちゃんが子宮外という全く新しい環境に適応するのを助けます。` } },
      { type: "paragraph", text: { en: `Before birth, though, the baby isn't operating on its own internal clock. Instead, its bodily rhythms — such as sleep patterns or internal cycles — are borrowed from the mother. The baby's nervous system develops in sync with her rhythms, almost like following her lead, while also slowly building its own independent rhythm in the background.`, ja: `しかし出生前、赤ちゃんは自分自身の体内時計で動いているわけではありません。むしろ、睡眠パターンや体内サイクルなどの身体リズムは、母親から借りている状態です。赤ちゃんの神経系は母親のリズムと同期しながら発達し、まるで彼女の導きに従うかのようでありながら、背景ではゆっくりと独自の独立したリズムを築いていきます。` } },
      { type: "paragraph", text: { en: `The exact moment a baby takes its first breath is significant. According to Jyotish (Vedic astrology), that specific moment captures a unique snapshot: a particular state of the Moon (representing hypothalamic activity) combined with a particular alignment of the Nakshatras (representing brainstem activity). This precise combination is believed to set the tone for the person's entire life journey — marking the beginning of their individual biological and astrological rhythm. From that point forward, life continues in structured cycles: the daily rhythm of day turning into night, the monthly rhythm of lunar phases, and many other natural patterns that shape our existence over time.`, ja: `赤ちゃんが最初の息を吸う正確な瞬間は、非常に重要です。ジョーティッシュ（ヴェーダ占星術）によれば、その特定の瞬間は唯一のスナップショットを捉えます — 月の特定の状態（視床下部の活動を表す）と、ナクシャトラの特定の配置（脳幹の活動を表す）の組み合わせです。この精密な組み合わせが、その人の生涯全体の基調を定めると信じられています — 個人の生物学的・占星術的リズムの始まりを刻むのです。その瞬間以降、人生は構造化されたサイクルの中で続きます — 昼が夜に変わる日々のリズム、月相の月次リズム、そして時間をかけて私たちの存在を形作るその他多くの自然のパターンです。` } },
    ],
  },
  {
    id: "planetary-forces",
    section: "introduction",
    title: { en: `Jyotish – Planetary Forces`, ja: `ジョーティッシュ – 惑星軍` },
    related: ["natural-benefics-malefics","planetary-strengths","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Planetary Forces`, ja: `ジョーティッシュ – 惑星軍` } },
      { type: "paragraph", text: { en: `Summary: This article addresses a common criticism made by some Western Astrologers regarding traditional Vedic Astrology—that it is limited or outdated because it uses only nine "planets." Jyotish maintains that there is no need to incorporate planets beyond Saturn, as it works directly with a field of perfectly codified information rather than with physical or subtle forces supposedly emitted by planets, asteroids, or other celestial bodies.`, ja: `概要: この記事は、伝統的なヴェーダ占星術に関して一部の西洋占星術師がよく行う批判、つまり、9 つの「惑星」しか使用していないため限界がある、または時代遅れであるという批判に対処します。ジョーティッシュは、惑星、小惑星、その他の天体から発せられるとされる物理的または微妙な力ではなく、完全に体系化された情報の分野と直接連携するため、土星以外の惑星を組み込む必要はないと主張している。` } },
      { type: "paragraph", text: { en: `Planetary ‘Forces’ Don’t Exist in Vedic Astrology`, ja: `惑星の「力」はヴェーダ占星術には存在しない` } },
      { type: "paragraph", text: { en: `Many Western Astrologers hold the view that planets—and even asteroids—emit some form of subtle influence or force, which has not yet been identified by modern science, and that these forces affect human life. Based on this assumption, they often argue that Jyotish Astrology is incomplete because it does not include the outer planets Uranus, Neptune, and Pluto, nor more recently recognized celestial objects such as Chiron.`, ja: `多くの西洋占星術師は、惑星、さらには小惑星が、現代科学ではまだ特定されていない何らかの形の微妙な影響や力を発しており、それらの力が人間の生活に影響を与えるという見解を持っています。この仮定に基づいて、ジョーティッシュ占星術には外惑星の天王星、海王星、冥王星や、最近になって認識されたキロンなどの天体が含まれていないため、彼らは不完全であると主張することがよくあります。` } },
      { type: "paragraph", text: { en: `However, as discussed below, Vedic Astrology approaches the subject from an entirely different perspective. Jyotish works directly with a field of structured and codified information that is complete in itself, rather than with any form of planetary force.`, ja: `ただし、以下で説明するように、ヴェーダ占星術はまったく異なる観点からこの主題にアプローチします。ジョーティッシュは、惑星の力ではなく、それ自体で完全な、構造化され体系化された情報のフィールドを直接操作します。` } },
      { type: "paragraph", text: { en: `Although Vedic Astrologers may occasionally use the phrase "planetary force" when communicating with clients, this should not be interpreted as referring to an actual physical force. Instead, it simply describes the influence or effect that a planet signifies within an individual's life.`, ja: `ヴェーダ占星術師はクライアントとコミュニケーションをとる際に「惑星の力」というフレーズを使用することがありますが、これを実際の物理的な力を指すものとして解釈すべきではありません。代わりに、個人の生活の中で惑星が意味する影響や効果を単に説明します。` } },
      { type: "heading", level: 3, text: { en: `Key Points in Support of the ‘Codified Information’ Viewpoint`, ja: `「コード化された情報」の観点をサポートする重要なポイント` } },
      { type: "paragraph", text: { en: `• Jyotish regards the planetary arrangements present at the moment of birth as a form of cosmic code. Skilled Vedic Astrologers interpret this code and translate it into predictions concerning returning karma carried over from previous incarnations.`, ja: `• ジョーティッシュは、誕生の瞬間に存在する惑星の配置を宇宙のコードの一種とみなします。熟練したヴェーダ占星術師はこのコードを解釈し、前世から引き継がれたカルマの帰還に関する予測に変換します。` } },
      { type: "paragraph", text: { en: `• The placement of the seven visible planets (up to and including Saturn), together with the two lunar nodes [1], within the twelve signs, twelve houses, and twenty-seven Nakshatras, represents a highly sophisticated system of encoded information. This information provides everything required for understanding the major areas of life—Dharma, Artha, Kama, and Moksha.`, ja: `• 目に見える 7 つの惑星 (土星まで) と 2 つの月のノード [1] の、12 のサイン、12 ハウス、27 のナクシャトラ内への配置は、コード化された情報の高度に洗練されたシステムを表しています。この情報は、人生の主要な領域であるダルマ、アルタ、カーマ、モクシャを理解するために必要なすべてを提供します。` } },
      { type: "paragraph", text: { en: `• Planetary transits, as planets appear to move through the sidereal zodiac signs and houses, are likewise viewed as expressions of codified information rather than manifestations of physical forces.`, ja: `• 惑星が恒星星座やハウスの中を移動しているように見える惑星の通過も、同様に、物理的な力の発現ではなく、体系化された情報の表現として見なされます。` } },
      { type: "paragraph", text: { en: `• The absence of any physical force is further supported by a fundamental Jyotish principle: the effects of planets vary significantly according to an individual's Ascendant or rising sign [2]. No comparable concept exists within traditional Western Astrology. The same planet can produce very different outcomes depending upon the Ascendant. If a genuine physical force were involved, such variations would be difficult to explain.`, ja: `• 物理的な力が存在しないことは、基本的なジョーティッシュの原則によってさらに裏付けられています。つまり、惑星の影響は個人のアセンダントまたはライジング サインに応じて大きく異なります [2]。伝統的な西洋占星術にはこれに匹敵する概念は存在しません。同じ惑星でもアセンダントに応じて非常に異なる結果が生じる可能性があります。本物の物理的な力が関与している場合、そのような変動を説明するのは困難でしょう。` } },
      { type: "paragraph", text: { en: `• Jyotish also places great importance on Rahu and Ketu, the Moon's nodes. These have no physical substance whatsoever. They are simply mathematically calculated points where the Moon's orbit intersects the ecliptic [3]. Yet they indicate major karmic influences and tangible life experiences. If these points possess no material existence, it becomes difficult to argue that their effects result from any physical force.`, ja: `• ジョーティッシュはまた、月のノードであるラーフとケートゥを非常に重要視します。これらには物理的な実体はまったくありません。それらは、月の軌道が黄道と交差する単純に数学的に計算された点です [3]。しかし、それらは大きなカルマ的影響と具体的な人生経験を示しています。これらの点が物質的な存在を持たない場合、その影響が物理的な力によるものであると主張するのは困難になります。` } },
      { type: "paragraph", text: { en: `• Vedic Astrologers traditionally believe that Jyotish was "revealed" or "cognized." It was neither invented by humanity nor developed gradually through experimentation. Rather, it is regarded as Divine Knowledge that is complete in itself. Within this divine system there is no requirement to incorporate information from the outer planets or recently discovered asteroids. To do so would be viewed as a departure from the original teachings of the great sage Maharishi Parashara.`, ja: `• ヴェーダ占星術師は伝統的に、ジョーティッシュは「啓示」または「認識」されたと信じています。それは人類によって発明されたものでも、実験によって徐々に開発されたものでもありません。むしろ、それ自体で完全な神聖な知識とみなされます。この神聖なシステム内では、外惑星や最近発見された小惑星からの情報を組み込む必要はありません。そうすることは、偉大な聖者マハリシ・パラシャラの本来の教えから逸脱するとみなされるでしょう。` } },
      { type: "paragraph", text: { en: `• The idea of complete and perfect knowledge being provided by the Divine for the benefit of humanity is not unique to Jyotish. Similar principles are found in other Vedic sciences such as Ayurveda, the Vedic system of natural healthcare, and Vastu, the science of designing harmonious living environments.`, ja: `・完全かつ完全な知識が人類の利益のために神によって提供されるという考えは、ジョーティッシュに特有のものではありません。同様の原理は、自然医療のヴェーダ システムであるアーユルヴェーダや、調和のとれた生活環境を設計する科学であるヴァストゥなど、他のヴェーダ科学にも見られます。` } },
      { type: "heading", level: 3, text: { en: `Jyotish Astrologers Interpret the ‘Cosmic Codes’`, ja: `ジョーティッシュ占星術師が「宇宙の暗号」を解釈する` } },
      { type: "paragraph", text: { en: `To fully appreciate the foundations of Jyotish, we must move beyond purely mechanistic models of reality. The traditional Newtonian view, based on objects and forces, gives way to a deeper understanding in which consciousness is regarded as the fundamental basis of existence. At its core, the functioning of Vedic Astrology rests upon the Vedic model of reality.`, ja: `ジョーティッシュの基礎を十分に理解するには、純粋に機械的な現実モデルを超えなければなりません。物体と力に基づく伝統的なニュートンの見方は、意識が存在の基本的な基盤であるとみなされる、より深い理解に取って代わられます。ヴェーダ占星術の機能の核心は、ヴェーダの現実モデルに基づいています。` } },
      { type: "paragraph", text: { en: `Jyotish emerges from a tradition that views the universe as one perfectly integrated whole. Underlying this totality is an all-pervading field of Cosmic Intelligence. In our essential nature, we are part of that Cosmic Intelligence. It is therefore not surprising that the intelligence responsible for creating the universe should also provide insights into our past, present, and potential future.`, ja: `ジョーティッシュは、宇宙を完全に統合された 1 つの全体として見る伝統から生まれました。この全体性の根底にあるのは、宇宙知性のあらゆる領域に浸透していることです。私たちの本質的な性質において、私たちは宇宙の知性の一部です。したがって、宇宙の創造に関与した知性が、私たちの過去、現在、そして潜在的な未来についての洞察も提供することは驚くべきことではありません。` } },
      { type: "paragraph", text: { en: `As the enlightened Vedic Master Sri Sri Ravi Shankar stated:`, ja: `啓発されたヴェーダのマスター、シュリ シュリ ラヴィ シャンカールは次のように述べています。` } },
      { type: "paragraph", text: { en: `"The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It's one Being, one consciousness, one Self, that manifests itself into this varied universe."`, ja: `「占星術の目的は、宇宙全体が一つの有機体であるという究極の真実にあなたを導くことです。この多様な宇宙に現れるのは、一つの存在、一つの意識、一つの自己です。」` } },
      { type: "paragraph", text: { en: `(Published in the Art of Living's Daily Sutra, May 2003.)`, ja: `(2003 年 5 月、『暮らしの日々の経典』に掲載。)` } },
      { type: "paragraph", text: { en: `In many respects, a birth chart can be compared to a strand of DNA within a sperm or egg cell. DNA stores vast amounts of information in an extremely condensed form. As time unfolds, that information is progressively expressed as tissues, organs, physical structures, and eventually a complete living being.`, ja: `多くの点で、出生図は精子または卵細胞内の DNA 鎖にたとえることができます。 DNA は、膨大な量の情報を非常に凝縮された形で保存します。時間が経つにつれて、その情報は組織、器官、物理的構造として徐々に表現され、最終的には完全な生命体として表現されます。` } },
      { type: "paragraph", text: { en: `A similar process occurs in Jyotish. The information encoded within a birth chart gradually unfolds through time, manifesting as significant life events and karmic experiences—whether beneficial or challenging.`, ja: `同様のプロセスがジョーティッシュでも発生します。出生図内にエンコードされた情報は、時間の経過とともに徐々に明らかになり、有益な場合でも困難な場合でも、重要な人生の出来事やカルマ的経験として現れます。` } },
      { type: "paragraph", text: { en: `Jyotish Astrology consists of numerous axioms and mathematical rules that enable the astrologer to interpret how the highly encoded information within a birth chart may unfold into physical circumstances and karmic outcomes. This process is somewhat analogous to modern biochemistry, which can decode sections of DNA and relate them to recognizable physical characteristics.`, ja: `ジョーティッシュ占星術は、占星術師が出生図内の高度に暗号化された情報が物理的状況やカルマ的結果にどのように展開するかを解釈できるようにする多数の公理と数学的規則で構成されています。このプロセスは、DNA のセクションを解読し、それらを認識可能な物理的特徴に関連付けることができる現代の生化学にある程度似ています。` } },
      { type: "paragraph", text: { en: `For this reason, Jyotish does not require the concept of forces being emitted by planets or celestial bodies. It works directly with a field of information and intelligence that is already complete and self-contained.`, ja: `このため、ジョーティッシュでは、惑星や天体から発せられる力の概念は必要ありません。それは、すでに完全で自己完結型の情報およびインテリジェンスの分野と直接連携します。` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `脚注` } },
      { type: "heading", level: 3, text: { en: `[1]`, ja: `[1]` } },
      { type: "paragraph", text: { en: `Jyotish utilizes nine Grahas, or celestial influences, often translated as "planets." These include the Sun and Moon (which are not classified as planets from an astronomical perspective), Mercury, Venus, Mars, Jupiter, and Saturn. It also includes two calculated points known as Rahu and Ketu, the Moon's nodes, which are closely associated with eclipses.`, ja: `ジョーティッシュは 9 つのグラハ、つまり「惑星」と訳されることもある天体の影響を利用します。これらには、太陽と月 (天文学的な観点からは惑星として分類されません)、水星、金星、火星、木星、土星が含まれます。また、月食と密接に関連するラーフとケトゥとして知られる 2 つの計算された点 (月のノード) も含まれています。` } },
      { type: "heading", level: 3, text: { en: `[2]`, ja: `[2]` } },
      { type: "paragraph", text: { en: `For example, in Jyotish the planet Mars is generally considered highly beneficial in the birth chart of an individual with a Leo Ascendant because it rules both the 4th house and the auspicious 9th house, thereby functioning as a functional benefic.`, ja: `たとえば、ジョーティッシュでは、火星は一般に、獅子座アセンダントを持つ個人の出生図において非常に有益であると考えられています。これは、火星が4室と縁起の良い9室の両方を支配しており、それによって機能的な恩恵として機能しているためです。` } },
      { type: "paragraph", text: { en: `By contrast, Mars is generally regarded as strongly unfavourable for someone with a Virgo Ascendant because it rules the 6th and 11th houses, making it both a functional and natural malefic.`, ja: `対照的に、火星は一般に、乙女座アセンダントを持つ人にとって非常に不利であると考えられています。これは、火星が6室と11室を支配しており、機能的かつ自然な凶星であるためです。` } },
      { type: "paragraph", text: { en: `Thus, the same planet can indicate positive outcomes for one individual and negative outcomes for another. Clearly, this cannot be explained by a physical force emanating from Mars itself. Rather, it supports the view that Jyotish operates through an integrated field of information or intelligence linking the individual to the Cosmic Totality.`, ja: `したがって、同じ惑星は、ある人にとってはポジティブな結果を示し、別の人にとってはネガティブな結果を示す可能性があります。明らかに、これは火星自体から発せられる物理的な力では説明できません。むしろ、ジョーティッシュは個人を宇宙の全体性に結び付ける統合された情報または知性の分野を通じて活動しているという見解を支持しています。` } },
      { type: "heading", level: 3, text: { en: `[3]`, ja: `[3]` } },
      { type: "paragraph", text: { en: `"The lunar nodes are the orbital nodes of the Moon, that is, the two points at which the orbit of the Moon crosses the ecliptic. The ascending (or north) node is where the Moon moves into the northern ecliptic hemisphere, while the descending (or south) node is where the Moon enters the southern ecliptic hemisphere. Eclipses involving the Moon occur only near the lunar nodes. A solar eclipse occurs when the passage of the Moon through a node coincides with the new moon, while a lunar eclipse occurs when the passage coincides with the full moon."`, ja: `「月の交点は、月の軌道の交点、つまり、月の軌道が黄道を横切る2つの点です。上昇（または北）交点は、月が黄道北半球に入る場所であり、下降（または南）交点は、月が黄道南半球に入る場所です。月が関係する日食は、月の交点の近くでのみ発生します。日食は、月の交点の近くでのみ発生します。月のノードを通過する部分が新月と一致し、月食はノードを通過する部分が満月と一致すると発生します。」` } },
    ],
  },
  {
    id: "forecasting-analogies-1",
    section: "introduction",
    title: { en: `Jyotish – Forecasting Analogies`, ja: `ジョーティッシュ – 予測のアナロジー` },
    related: ["predictive-capabilities","cosmos-individual-1","jyotish-and-karma"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Forecasting Analogies`, ja: `ジョーティッシュ – 予測のアナロジー` } },
      { type: "paragraph", text: { en: `Summary: This article explores several analogies commonly used to explain the probabilistic nature of prediction in Vedic Astrology. These comparisons help illustrate how planetary arrangements can be used to assess the likelihood of future events and influences unfolding in an individual's life.`, ja: `概要: この記事では、ヴェーダ占星術における予測の確率的性質を説明するために一般的に使用されるいくつかのアナロジーを検討します。これらの比較は、個人の人生に展開する将来の出来事や影響の可能性を評価するために惑星の配置がどのように使用できるかを説明するのに役立ちます。` } },
      { type: "heading", level: 3, text: { en: `Forecasting Analogies in Vedic Astrology`, ja: `ヴェーダ占星術における予測の類似点` } },
      { type: "heading", level: 3, text: { en: `Weather Forecasting Analogy`, ja: `天気予報のたとえ` } },
      { type: "paragraph", text: { en: `Vedic Astrology is fundamentally probabilistic in nature. In this respect, it can be compared to a long-range weather forecasting system. Jyotish seeks to predict when and how the actions we have performed in the past—our accumulated karmas—are likely to return as present and future influences in our lives.`, ja: `ヴェーダ占星術は基本的に確率的な性質を持っています。この点で、これは長期天気予報システムと比較できます。ジョーティッシュは、私たちが過去に行った行動、つまり蓄積されたカルマが、私たちの生活に現在および将来の影響としていつどのように戻ってくるかを予測しようとしています。` } },
      { type: "paragraph", text: { en: `If potential "storms" can be seen approaching on the horizon, we have the opportunity to take appropriate action and reduce difficulties before they fully manifest. Likewise, when "fine weather" is indicated, we can move forward more easily, make progress, and fulfil our desires with less resistance.`, ja: `潜在的な「嵐」が地平線に近づいているのが見える場合、私たちはそれが完全に現れる前に適切な行動をとり、困難を軽減する機会があります。同様に、「晴天」が示されると、より抵抗が少なくなり、より簡単に前進し、進歩し、欲望を達成することができます。` } },
      { type: "paragraph", text: { en: `Just as meteorologists cannot guarantee 100% accuracy in every forecast, Jyotish is not an exact science. Experienced and skilled Vedic Astrologers are generally considered capable of achieving prediction accuracies in the region of 70%. However, when numerous factors within a birth chart consistently point toward benefits or challenges in a particular area of life, the astrologer can make predictions with a much greater degree of confidence.`, ja: `気象学者がすべての予報で 100% の正確性を保証できないのと同じように、ジョーティッシュは正確な科学ではありません。経験豊富で熟練したヴェーダ占星術師は、一般的に 70% 程度の予測精度を達成できると考えられています。ただし、出生図内の数多くの要素が人生の特定の分野における利点や課題を一貫して示している場合、占星術師はより高い自信を持って予測を行うことができます。` } },
      { type: "heading", level: 3, text: { en: `Seed Development Analogy`, ja: `シード開発のアナロジー` } },
      { type: "paragraph", text: { en: `Different seeds produce different types of trees. A botanist can examine two seeds and confidently predict that one will develop into a silver birch and the other into a redwood. Most people find nothing unusual about such a prediction.`, ja: `種が異なれば、異なる種類の木が生まれます。植物学者は 2 つの種子を調べて、1 つはシラカバに、もう 1 つはセコイアに成長すると確信を持って予測できます。ほとんどの人は、そのような予測に何の異常も感じません。` } },
      { type: "paragraph", text: { en: `The botanist cannot determine exactly how many branches each tree will eventually have, nor can he state its precise height, since these factors depend upon soil quality, climate, and environmental conditions. Likewise, he cannot predict the exact lifespan of each tree. Nevertheless, he can accurately describe their general characteristics and growth patterns.`, ja: `植物学者は、各木が最終的に何本の枝を持つことになるかを正確に決定することはできません。また、その正確な高さを言うこともできません。これらの要因は土壌の質、気候、環境条件に依存するためです。同様に、各木の正確な寿命を予測することもできません。それにもかかわらず、彼は彼らの一般的な特徴と成長パターンを正確に説明することができます。` } },
      { type: "paragraph", text: { en: `A birth chart can be viewed in much the same way as a seed. Therefore, it should not be surprising that Vedic Astrologers are able to predict broad life trends and tendencies.`, ja: `出生図はシードとほぼ同じように見ることができます。したがって、ヴェーダ占星術師が幅広い人生の傾向や傾向を予測できることは驚くべきことではありません。` } },
      { type: "paragraph", text: { en: `We know that the structure and characteristic development of a tree are encoded within the DNA contained in its seed. In a similar manner, the probable effects of our returning karmas—which themselves unfold according to the laws of nature—are reflected in the "code" contained within the planetary arrangements of the birth chart.`, ja: `木の構造と特徴的な発達は、その種子に含まれる DNA 内にコード化されていることがわかっています。同様に、私たちが戻ってくるカルマの起こり得る影響は、それ自体が自然の法則に従って展開され、出生図の惑星配置に含まれる「コード」に反映されます。` } },
      { type: "paragraph", text: { en: `This viewpoint suggests that our time of birth is not merely a random event. Instead, it reflects the Vedic understanding that all life and matter are interconnected within a unified universe.`, ja: `この視点は、私たちの誕生の時期が単なる偶然の出来事ではないことを示唆しています。むしろ、すべての生命と物質は統一された宇宙の中で相互に結びついているというヴェーダの理解を反映しています。` } },
      { type: "heading", level: 3, text: { en: `Road Map Analogy`, ja: `ロードマップの類似点` } },
      { type: "paragraph", text: { en: `Vedic Astrology offers a perspective that transcends ordinary limitations of space and time. Rather than travelling along an unfamiliar road without guidance, it provides a view from above—almost as if observing the journey from a helicopter.`, ja: `ヴェーダ占星術は、通常の空間と時間の制限を超えた視点を提供します。案内なしで見知らぬ道を進むのではなく、まるでヘリコプターから旅を観察しているかのように、上空からの景色を眺めることができます。` } },
      { type: "paragraph", text: { en: `From this higher vantage point, future turns, changes in terrain, and road conditions become visible before we encounter them. It is similar to navigating with a map instead of attempting to find the way without one.`, ja: `この高い見晴らしの良い地点からは、将来の曲がり角、地形の変化、道路状況が、それらに遭遇する前に見えるようになります。これは、地図を使わずに道を探すのではなく、地図を使ってナビゲートすることに似ています。` } },
      { type: "paragraph", text: { en: `Certain areas of life may resemble smooth, straight roads where progress comes easily. Other areas may contain bends, obstacles, or difficult terrain that require greater attention and care. These favourable and challenging periods also change over time as we move through life's journey.`, ja: `人生の特定の領域は、進歩が容易な滑らかでまっすぐな道に似ているかもしれません。他のエリアには、より注意と注意が必要な曲がり角、障害物、または困難な地形が含まれる場合があります。これらの有利な時期と困難な時期も、人生の旅路を進むにつれて時間の経過とともに変化します。` } },
      { type: "paragraph", text: { en: `Having access to the perspective offered by Vedic Astrology can therefore make life easier to navigate and potentially more fulfilling, as it helps us understand what may lie ahead and prepare accordingly.`, ja: `したがって、ヴェーダ占星術が提供する視点にアクセスできれば、今後何が待ち受けているかを理解し、それに応じて準備するのに役立つため、人生をよりナビゲートしやすくなり、潜在的により充実したものにすることができます。` } },
    ],
  },
  {
    id: "cosmos-individual-1",
    section: "introduction",
    title: { en: `Relationship Between the Cosmos and the Individual`, ja: `宇宙と個人の関係` },
    related: ["forecasting-analogies-1","planetary-forces","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Relationship Between the Cosmos and the Individual`, ja: `宇宙と個人の関係` } },
      { type: "paragraph", text: { en: `Jyotish Astrology reveals the relationship between the cosmic totality and individual reality. The complete system of sidereal astrology was cognized by the ancient sage Maharishi Parashara, who is said to have revealed the mathematical and astronomical principles used to forecast future trends and prescribe remedial measures designed to minimise potential difficulties.`, ja: `ジョーティッシュ占星術は、宇宙の全体性と個人の現実との関係を明らかにします。恒星占星術の完全なシステムは古代の聖者マハリシ・パラシャラによって認識され、将来の傾向を予測し、潜在的な困難を最小限に抑えるための是正措置を処方するために使用される数学的および天文学的な原理を明らかにしたと言われています。` } },
      { type: "paragraph", text: { en: `According to this understanding, the cosmos is an intelligently organised and deeply interconnected whole. Events do not occur in isolation; rather, one event naturally leads to another through an ongoing process of unfoldment.`, ja: `この理解によれば、宇宙は知的に組織化され、深く相互接続された全体です。イベントは単独で発生するわけではありません。むしろ、ある出来事は進行中の展開プロセスを通じて自然に別の出来事につながります。` } },
      { type: "paragraph", text: { en: `From this perspective, the future can be understood by interpreting the code contained within the planetary arrangements present at the time of birth. Through this cosmic blueprint, Jyotish seeks to reveal the relationship between individual experience and the greater intelligence that governs the universe.`, ja: `この観点から、誕生時に存在する惑星配置に含まれるコードを解釈することで、未来を理解することができます。ジョーティッシュは、この宇宙の青写真を通じて、個人の経験と宇宙を支配するより大きな知性との関係を明らかにしようとしています。` } },
    ],
  },
  {
    id: "planetary-antidotes",
    section: "remedies",
    title: { en: `Planetary Antidotes in Jyotish`, ja: `ジョーティッシュの惑星解毒剤` },
    related: ["gemstones","mantras","preventive-capabilities"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Planetary Antidotes in Jyotish`, ja: `ジョーティッシュの惑星解毒剤` } },
      { type: "paragraph", text: { en: `Summary: This article explores Remedial Measures or Planetary Antidotes (Upaye or Upayes) in Jyotish. It includes a detailed discussion of wearing gemstones associated with specific planets, chanting planetary mantras, performing charitable acts, and conducting Vedic rituals to harmonise planetary energies.`, ja: `概要: この記事では、ジョーティッシュにおける救済策または惑星の解毒剤 (Upaye または Upayes) について探ります。これには、特定の惑星に関連付けられた宝石の着用、惑星のマントラの唱え、慈善行為の実行、惑星のエネルギーを調和させるためのヴェーダ儀式の実施についての詳細な議論が含まれています。` } },
      { type: "heading", level: 3, text: { en: `Planetary Antidotes (Upaye) – Remedial Measures in Jyotish`, ja: `惑星の解毒剤 (Upaye) – ジョーティッシュの救済措置` } },
      { type: "paragraph", text: { en: `Vedic Astrology is fundamentally karmic in nature. It predicts both the type and duration of positive and negative returning karma, helping us understand what experiences are likely to arise in different areas of life and, perhaps most importantly, when they are likely to occur.`, ja: `ヴェーダ占星術は基本的にカルマ的な性質を持っています。これは、ポジティブなカルマとネガティブなカルマの種類と期間の両方を予測し、人生のさまざまな分野でどのような経験が発生する可能性があるのか​​、そしておそらく最も重要なのは、それらがいつ発生する可能性があるのか​​を理解するのに役立ちます。` } },
      { type: "paragraph", text: { en: `One of the great strengths of Jyotish is that it comes from a tradition which teaches that suffering is not inevitable. It is therefore no surprise that Jyotish provides a range of practical techniques designed to deflect, minimise, or greatly reduce the effects of returning negative karma. These methods are commonly known as remedial measures or planetary antidotes (Upaye or Upayes).`, ja: `ジョーティッシュの大きな強みの 1 つは、苦しみは避けられないものであると教える伝統に由来していることです。したがって、ジョーティッシュが、戻ってくる負のカルマの影響を逸らし、最小限に抑え、または大幅に軽減するように設計された一連の実践的なテクニックを提供することは驚くべきことではありません。これらの方法は一般に、救済措置または惑星の解毒剤 (Upaye または Upayes) として知られています。` } },
      { type: "paragraph", text: { en: `A Vedic Astrologer can identify imbalances within an individual's birth chart by interpreting the code represented by the planetary positions at birth. Based on this analysis, practical recommendations can be given to help "avert the danger that has not yet arisen." While these remedies may not completely eliminate karma, they can certainly modify its effects and lessen its impact.`, ja: `ヴェーダ占星術師は、出生時の惑星の位置によって表されるコードを解釈することで、個人の出生図内のアンバランスを特定できます。この分析に基づいて、「まだ生じていない危険を回避する」ための実践的な推奨事項を与えることができます。これらの治療法はカルマを完全に取り除くことはできないかもしれませんが、確実にその効果を修正し、その影響を軽減することができます。` } },
      { type: "paragraph", text: { en: `Planetary remedies are intended to balance negative planetary influences and restore greater harmony and equilibrium in life. They can also strengthen positive planetary influences, thereby maximising favourable returning karmas.`, ja: `惑星のレメディは、惑星のマイナスの影響のバランスを取り、人生におけるより大きな調和と平衡を回復することを目的としています。また、惑星のポジティブな影響を強化し、それによって戻ってくる好ましいカルマを最大化することもできます。` } },
      { type: "paragraph", text: { en: `The remedial measures prescribed in Jyotish generally fall into four main categories:`, ja: `ジョーティッシュで規定されている是正措置は、通常、次の 4 つの主要なカテゴリに分類されます。` } },
      { type: "paragraph", text: { en: `• Wearing gemstones associated with a particular planet`, ja: `• 特定の惑星に関連した宝石を身につける` } },
      { type: "paragraph", text: { en: `• Chanting planetary-related mantras`, ja: `• 惑星関連のマントラを唱える` } },
      { type: "paragraph", text: { en: `• Performing specific acts of charity`, ja: `• 特定の慈善行為の実行` } },
      { type: "paragraph", text: { en: `• Conducting Vedic rituals to balance planetary energies`, ja: `• 惑星エネルギーのバランスをとるためのヴェーダ儀式の実施` } },
      { type: "paragraph", text: { en: `These remedies are not based on superstition. They have survived the test of time through countless generations. Their effectiveness is rooted in the Vedic understanding that everything in the universe is interconnected. This Vedic Model of Reality is increasingly finding support from modern scientific perspectives and is also reflected in the Vedic and Buddhist concept of Indra's Net [1].`, ja: `これらの治療法は迷信に基づいたものではありません。彼らは数え切れないほどの世代を経て、時の試練を乗り越えてきました。その有効性は、宇宙のすべてが相互につながっているというヴェーダの理解に根ざしています。このヴェーダの現実モデルは、現代科学の観点からますます支持されており、ヴェーダと仏教のインドラの網の概念にも反映されています [1]。` } },
      { type: "paragraph", text: { en: `There is a famous lyric from a song by Joni Mitchell released in 1970: "We are stardust, we are golden." From the perspective of modern astrophysics, this is remarkably true. Nearly all the elements that make up the human body, apart from hydrogen, were forged in the interiors of stars billions of years ago. We therefore have a genuine connection with the stars because much of the material from which we are made originated there. Many people report that wearing a high-quality Jyotish gemstone reminds them of this connection at a very deep level.`, ja: `1970年にリリースされたジョニ・ミッチェルの曲に「私たちはスターダスト、私たちは黄金だ」という有名な歌詞があります。現代の天体物理学の観点から見ると、これは驚くほど真実です。水素を除く人体を構成するほぼすべての元素は、数十億年前に星の内部で作られました。したがって、私たちは星と真のつながりを持っています。なぜなら、私たちが作られている物質の多くは星から来ているからです。多くの人が、高品質のジョーティッシュの宝石を身に着けると、このつながりを非常に深いレベルで思い出させると報告しています。` } },
      { type: "paragraph", text: { en: `Although not specifically discussed in the classical Jyotish texts, many astrologers also agree that spiritual practices can significantly modify returning karma. In particular, mantra-based Vedic meditation techniques appear to have a profound effect. When astrologers examined the birth charts of long-term meditators, they often found that their actual life experiences were considerably more favourable than the charts alone might have suggested.`, ja: `古典的なジョーティッシュの文献では特に議論されていませんが、多くの占星術師は、スピリチュアルな実践が戻ってくるカルマを大幅に変える可能性があることに同意しています。特に、マントラに基づいたヴェーダ瞑想テクニックは深い効果があるようです。占星術師が長期瞑想者の出生図を調べたとき、彼らの実際の人生経験は、図だけが示唆するよりもかなり好ましいことがよくわかりました。` } },
      { type: "paragraph", text: { en: `For those fortunate enough to have a personal Guru, the Grace of the Guru can remove major obstacles from life. Such individuals should consider themselves especially blessed.`, ja: `個人的なグルを持つ幸運な人にとって、グルの恩寵は人生から大きな障害を取り除くことができます。そのような人は自分が特に恵まれていると考えるべきです。` } },
    ],
  },
  {
    id: "gemstones",
    section: "remedies",
    title: { en: `Wearing Gemstones as Planetary Antidotes`, ja: `惑星の解毒剤として宝石を身につける` },
    related: ["planetary-antidotes","mantras","natural-benefics-malefics"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Wearing Gemstones as Planetary Antidotes`, ja: `惑星の解毒剤として宝石を身につける` } },
      { type: "paragraph", text: { en: `In Vedic Astrology, every planet is associated with a specific gemstone. For example, the Sun corresponds to ruby, Venus to diamond, and Saturn to blue sapphire. When an auspicious planet in the birth chart requires strengthening—and in Jyotish a stronger auspicious planet is generally beneficial—wearing the gemstone associated with that planet can help amplify its positive influence.`, ja: `ヴェーダ占星術では、すべての惑星は特定の宝石に関連付けられています。たとえば、太陽はルビー、金星はダイヤモンド、土星はブルー サファイアに対応します。出生図の縁起の良い惑星が強化を必要とする場合、そしてジョーティッシュでは、より強力な縁起の良い惑星は一般的に有益です。その惑星に関連付けられた宝石を身に着けることで、そのポジティブな影響を増幅させることができます。` } },
      { type: "paragraph", text: { en: `The key word here is auspicious. Only auspicious planets should be strengthened through gemstones. In this context, auspicious means a functional benefic. If a planet is not auspicious for a particular Ascendant, alternative remedial measures, such as mantras, are generally recommended instead.`, ja: `The key word here is auspicious.縁起の良い惑星だけを宝石を通じて強化する必要があります。この文脈での縁起は、機能的な利益を意味します。特定のアセンダントにとって惑星が縁起が良くない場合は、通常、代わりにマントラなどの代替手段が推奨されます。` } },
      { type: "paragraph", text: { en: `Unfortunately, some modern Jyotish books fail to explain this important distinction clearly, which can lead to serious misunderstandings.`, ja: `残念ながら、現代のジョーティッシュの本の中にはこの重要な違いを明確に説明していないものがあり、重大な誤解を招く可能性があります。` } },
      { type: "paragraph", text: { en: `Because many planets rule two houses simultaneously, determining whether a planet is favourable or unfavourable for a particular Ascendant can become quite complex. As the Ascendant changes within the Sidereal Zodiac, the functional benefic or functional malefic nature of a planet also changes.`, ja: `多くの惑星は 2 つのハウスを同時に支配しているため、ある惑星が特定のアセンダントにとって有利か不利かを判断することは非常に複雑になる可能性があります。恒星黄道帯内でアセンダントが変化すると、惑星の機能的有益性または機能的凶悪性の性質も変化します。` } },
      { type: "paragraph", text: { en: `This topic is discussed in greater detail elsewhere, but as a broad guideline—and Jyotish always has exceptions—any planet ruling the first, fifth, or ninth house is generally considered auspicious regardless of any secondary house ownership.`, ja: `このトピックについては他の場所で詳しく説明されていますが、大まかなガイドラインとして、ジョーティッシュには常に例外がありますが、第 2 ハウスの所有権に関係なく、第 1、第 5、または第 9 ハウスを支配する惑星は一般に縁起が良いと考えられます。` } },
      { type: "heading", level: 3, text: { en: `Planet and Gemstone Associations in Jyotish`, ja: `ジョーティッシュの惑星と宝石協会` } },
      { type: "paragraph", text: { en: `The traditional gemstone associations for the nine planets are as follows:`, ja: `9 つの惑星の伝統的な宝石の関連付けは次のとおりです。` } },
      { type: "paragraph", text: { en: `• Sun – Ruby`, ja: `• サン – ルビー` } },
      { type: "paragraph", text: { en: `• Moon – Pearl`, ja: `• ムーン – パール` } },
      { type: "paragraph", text: { en: `• Mars – Red Coral`, ja: `• 火星 – 赤珊瑚` } },
      { type: "paragraph", text: { en: `• Mercury – Emerald`, ja: `• 水銀 – エメラルド` } },
      { type: "paragraph", text: { en: `• Jupiter – Yellow Sapphire`, ja: `• ジュピター – イエロー サファイア` } },
      { type: "paragraph", text: { en: `• Venus – Diamond`, ja: `• 金星 – ダイヤモンド` } },
      { type: "paragraph", text: { en: `• Saturn – Blue Sapphire`, ja: `• 土星 – ブルーサファイア` } },
      { type: "paragraph", text: { en: `• Rahu – Gomed (Hessonite Garnet)`, ja: `• ラーフ – ゴメッド (ヘソナイト ガーネット)` } },
      { type: "paragraph", text: { en: `• Ketu – Cat's Eye (Chrysoberyl)`, ja: `• Ketu – キャッツアイ (クリソベリル)` } },
      { type: "paragraph", text: { en: `Note: Gomed is also known as Hessonite Garnet, while Cat's Eye generally refers to Chrysoberyl.`, ja: `注: ゴメッドはヘソナイト ガーネットとしても知られていますが、キャッツアイは一般的にクリソベリルを指します。` } },
      eduImage(educationImages.gemstone1, {
        en: "Planet and gemstone associations in Jyotish (1)",
        ja: "ジョーティッシュにおける惑星と宝石の対応（1）",
      }),
      eduImage(educationImages.gemstone2, {
        en: "Planet and gemstone associations in Jyotish (2)",
        ja: "ジョーティッシュにおける惑星と宝石の対応（2）",
      }),
      eduImage(educationImages.gemstone3, {
        en: "Planet and gemstone associations in Jyotish (3)",
        ja: "ジョーティッシュにおける惑星と宝石の対応（3）",
      }),
      { type: "paragraph", text: { en: `Jyotish is also very specific regarding the weight and quality of gemstones, the metal in which they should be set, and even the finger on which they should be worn [2]. For remedial purposes, gemstones should ideally be natural rather than synthetic or laboratory-created [3].`, ja: `ジョーティッシュはまた、宝石の重量と品質、宝石をはめ込む金属、さらには宝石を着用する指にさえも非常にこだわりがあります [2]。修復目的の場合、宝石は合成または実験室で作成されたものではなく、天然のものであることが理想的です [3]。` } },
      { type: "paragraph", text: { en: `To be effective, gemstones should remain in contact with the skin. This is typically achieved through specially designed ring settings or by wearing the stone as a pendant.`, ja: `効果を発揮するには、宝石が肌に触れたままにする必要があります。これは通常、特別にデザインされたリングのセッティング、または石をペンダントとして着用することによって実現されます。` } },
      { type: "paragraph", text: { en: `Some Jyotish experts even suggest that the gold itself—provided it is 22-carat quality—may reduce a significant proportion of planetary negativity when worn in a chain or ring. If correct, this is certainly an interesting observation.`, ja: `一部のジョーティッシュ専門家は、金自体が（22カラットの品質であれば）チェーンやリングに身に着けると、惑星のネガティブな要素のかなりの部分を軽減できる可能性があるとさえ示唆しています。もし正しければ、これは確かに興味深い観察です。` } },
      { type: "paragraph", text: { en: `Compared with Western Astrology, the use of gemstones in Jyotish is far more personalised. Western systems typically assign a birthstone based upon an individual's Sun sign, whereas Vedic Astrology recommends gemstones based upon a detailed analysis of the entire birth chart.`, ja: `Compared with Western Astrology, the use of gemstones in Jyotish is far more personalised.西洋のシステムでは通常、個人の太陽星座に基づいて誕生石を割り当てますが、ヴェーダ占星術では出生図全体の詳細な分析に基づいて宝石を推奨します。` } },
      { type: "heading", level: 3, text: { en: `Semi-Precious Gemstone Equivalents`, ja: `半貴石相当品` } },
      { type: "paragraph", text: { en: `If a high-quality precious gemstone is beyond our budget, certain semi-precious alternatives may be used. However, the general understanding is that they do not offer the same level of benefit or protection as the traditional precious stones.`, ja: `高品質の貴石が予算を超える場合は、特定の半貴石の代替品が使用される場合があります。しかし、一般的には、従来の宝石と同じレベルの利益や保護は提供されないということが理解されています。` } },
      { type: "paragraph", text: { en: `In India, the following alternatives are commonly used:`, ja: `インドでは、次の代替手段が一般的に使用されます。` } },
      { type: "paragraph", text: { en: `• Red Spinel for the Sun`, ja: `• 太陽のレッドスピネル` } },
      { type: "paragraph", text: { en: `• Green Tourmaline for Mercury`, ja: `• 水銀のグリーントルマリン` } },
      { type: "paragraph", text: { en: `• Yellow Topaz (preferred) or Yellow Citrine for Jupiter`, ja: `• 木星にはイエロー トパーズ (推奨) またはイエロー シトリン` } },
      { type: "paragraph", text: { en: `• White Sapphire or Phenakite for Venus`, ja: `• 金星の場合はホワイトサファイアまたはフェナカイト` } },
      { type: "paragraph", text: { en: `• Blue Spinel for Saturn`, ja: `• 土星のブルースピネル` } },
      { type: "heading", level: 3, text: { en: `Wearing Gemstones Based on our Ascendant`, ja: `アセンダントに基づいた宝石を身につける` } },
      { type: "paragraph", text: { en: `If we know our Ascendant, or rising sign in the Sidereal Zodiac, we can safely wear the gemstone associated with the planet ruling that sign. This is considered a universally beneficial remedy and is something almost everyone can do to receive positive results.`, ja: `自分のアセンダント、つまり恒星黄道帯の上昇星座を知っていれば、その星座を支配する惑星に関連付けられた宝石を安全に身につけることができます。これは普遍的に有益な治療法と考えられており、ほぼすべての人がポジティブな結果を得るために実行できることです。` } },
      { type: "paragraph", text: { en: `By strengthening the Ascendant Lord—the planet ruling the Ascendant—we also strengthen the overall chart. This can provide some assistance in mitigating difficulties shown elsewhere in the horoscope, although not to the same extent as remedies specifically targeted toward individual planetary issues.`, ja: `アセンダントロード（アセンダントを支配する惑星）を強化することで、チャート全体も強化します。これは、個々の惑星の問題を特に対象とした治療法と同程度ではありませんが、星占いの他の場所で示されている困難を軽減するのにある程度の助けとなります。` } },
      { type: "paragraph", text: { en: `Strengthening the Ascendant Lord generally produces positive effects. Some astrologers note a possible exception for Scorpio Ascendants because Mars rules both the first and sixth houses.`, ja: `アセンダントロードを強化すると、一般にプラスの効果が得られます。一部の占星術師は、火星が第 1 室と第 6 室の両方を支配しているため、蠍座のアセンダントについては例外の可能性があると指摘しています。` } },
      { type: "paragraph", text: { en: `If we already possess a Western-style birth chart based on the Tropical Zodiac, conversion to the Sidereal Zodiac can be achieved by subtracting the relevant Ayanamsha for the birth date [4]. Once this is done, the appropriate gemstone can be selected.`, ja: `熱帯黄道帯に基づいた西洋式出生図をすでに所有している場合は、生年月日から関連するアヤナムシャを減算することで恒星黄道帯への変換を達成できます [4]。これが完了すると、適切な宝石を選択できます。` } },
      { type: "paragraph", text: { en: `Alternatively, various online tools based upon the Sidereal Zodiac can provide gemstone recommendations. Accurate birth times are essential for reliable results. If uncertainty exists regarding birth time, it is wise to compare multiple reports or consult an experienced Vedic Astrologer.`, ja: `あるいは、恒星黄道帯に基づいたさまざまなオンライン ツールで、推奨宝石を提供することもできます。信頼性の高い結果を得るには、正確な出生時刻が不可欠です。出生時刻に関して不確実性がある場合は、複数のレポートを比較するか、経験豊富なヴェーダ占星術師に相談することが賢明です。` } },
    ],
  },
  {
    id: "mantras",
    section: "remedies",
    title: { en: `Chanting Planetary Related Mantras to Remove Negative Karma`, ja: `惑星関連のマントラを唱えてネガティブなカルマを取り除く` },
    related: ["gemstones","vedic-rituals","charity"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Chanting Planetary Related Mantras to Remove Negative Karma`, ja: `惑星関連のマントラを唱えてネガティブなカルマを取り除く` } },
      { type: "paragraph", text: { en: `While gemstones can strengthen auspicious planets, wearing the gemstone associated with a functional malefic planet may actually increase difficulties. In such cases, chanting planetary mantras is often the preferred remedy.`, ja: `宝石は縁起の良い惑星を強化することができますが、機能的な凶星に関連付けられた宝石を身に着けると、実際には困難が増す可能性があります。そのような場合、惑星のマントラを唱えることが多くの場合好まれる治療法となります。` } },
      { type: "paragraph", text: { en: `Mantras are traditionally recited in Sanskrit and are said to "upwardly manage" the forces of nature, or Devas. Specific mantras can be used to harmonise negative planetary influences. In a sense, mantras act like passwords that connect us to higher levels of consciousness and facilitate transcendence.`, ja: `マントラは伝統的にサンスクリット語で唱えられ、自然の力、つまりデーヴァを「上向きに管理する」と言われています。特定のマントラを使用して、惑星のマイナスの影響を調和させることができます。ある意味、マントラは私たちをより高い意識レベルに結びつけ、超越を促進するパスワードのような役割を果たします。` } },
      { type: "paragraph", text: { en: `A Jyotish Astrologer can identify problematic planets in a birth chart and recommend suitable mantras to reduce their negative effects.`, ja: `ジョーティッシュ占星術師は、出生図で問題のある惑星を特定し、その悪影響を軽減するために適切なマントラを推奨します。` } },
      { type: "paragraph", text: { en: `At their simplest, planetary mantras generally follow the pattern:`, ja: `最も単純な惑星のマントラは、一般に次のパターンに従います。` } },
      { type: "paragraph", text: { en: `"Om – [Planet's Sanskrit Name] – Namaha"`, ja: `「オーム – [惑星のサンスクリット名] – ナマハ」` } },
      { type: "paragraph", text: { en: `These are commonly repeated 108 times daily using a mala or rosary. The number 108 is derived from the nine planets multiplied by the twelve zodiac signs (9 × 12 = 108).`, ja: `これらは通常、数珠やロザリオを使用して毎日 108 回繰り返されます。 108 という数字は、9 つ​​の惑星と 12 の星座を掛け合わせたものです (9 × 12 = 108)。` } },
      { type: "paragraph", text: { en: `For example, the mantra for Venus is:`, ja: `たとえば、金星のマントラは次のとおりです。` } },
      { type: "paragraph", text: { en: `"Om Shukraya Namaha"`, ja: `「オーム・シュクラヤ・ナマハ」` } },
      { type: "heading", level: 3, text: { en: `Basic Planetary Mantras to Chant`, ja: `唱えるべき基本的な惑星マントラ` } },
      { type: "paragraph", text: { en: `• Sun: Om Suryaya Namaha`, ja: `• 日曜日: オーム スーリヤヤ ナマハ` } },
      { type: "paragraph", text: { en: `• Moon: Om Somaya Namaha`, ja: `• 月: オーム ソマヤ ナマハ` } },
      { type: "paragraph", text: { en: `• Mars: Om Mangalaya Namaha`, ja: `• 火星：オーム マンガラヤ ナマハ` } },
      { type: "paragraph", text: { en: `• Mercury: Om Budhaya Namaha`, ja: `• 水星：オーム・ブダヤ・ナマハ` } },
      { type: "paragraph", text: { en: `• Jupiter: Om Brihaspataye Namaha`, ja: `• 木星：オーム・ブリハスパタエ・ナマハ` } },
      { type: "paragraph", text: { en: `• Venus: Om Shukraya Namaha`, ja: `• 金星：オーム・シュクラヤ・ナマハ` } },
      { type: "paragraph", text: { en: `• Saturn: Om Shanaye Namaha`, ja: `• 土星：オーム・シャナイ・ナマハ` } },
      { type: "paragraph", text: { en: `• Rahu: Om Rahave Namaha`, ja: `• ラーフ：オーム・ラハベ・ナマハ` } },
      { type: "paragraph", text: { en: `• Ketu: Om Ketave Namaha`, ja: `• ケトゥ: オム・ケタベ・ナマハ` } },
      { type: "paragraph", text: { en: `Because correct pronunciation is important, it is advisable to learn from a reputable source.`, ja: `正しい発音は重要なので、信頼できる情報源から学ぶことをお勧めします。` } },
      { type: "paragraph", text: { en: `A Jyotish Astrologer may further refine the remedy by identifying the periods during which a planet's influence is strongest—particularly during its Maha Dasha—and recommending chanting during that specific timeframe.`, ja: `ジョーティッシュ占星術師は、惑星の影響が最も強い期間、特にマハ・ダシャーの期間を特定し、その特定の期間に詠唱することを推奨することで、この治療法をさらに改良する可能性があります。` } },
      { type: "heading", level: 3, text: { en: `Mantra for Harmony Between the Nine Planets`, ja: `9つの惑星間の調和のためのマントラ` } },
      { type: "paragraph", text: { en: `Another option is the powerful Nav Graha mantra, which seeks to harmonise the energies of all nine planets simultaneously:`, ja: `もう 1 つのオプションは、9 つ​​の惑星すべてのエネルギーを同時に調和させようとする強力なナヴ グラハ マントラです。` } },
      { type: "paragraph", text: { en: `adityaaya cha somaaya mangalaaya budhaaya cha |`, ja: `アディティヤヤ チャ ソマーヤ マンガラヤ ブダヤヤ チャ |` } },
      { type: "paragraph", text: { en: `guru shukra shanibhyash cha raahave ketave namaha ||`, ja: `グル シュクラ シャニビヤシュ チャ ラーハベ ケタブ ナマハ ||` } },
      { type: "paragraph", text: { en: `This mantra is relatively easy to learn through regular repetition.`, ja: `このマントラは定期的に繰り返すことで比較的簡単に習得できます。` } },
      { type: "heading", level: 3, text: { en: `General Mantras for Removing Negativity and Suffering`, ja: `否定性と苦しみを取り除くための一般的なマントラ` } },
      { type: "paragraph", text: { en: `A widely recommended mantra is:`, ja: `広く推奨されるマントラは次のとおりです。` } },
      { type: "paragraph", text: { en: `"Auṁ Namaḥ Śivāya" (Om Namah Shivaya)`, ja: `「Auṁ Namaḥ Śivāya」（オーム ナマ シヴァーヤ）` } },
      { type: "paragraph", text: { en: `This simple yet powerful mantra is traditionally believed to remove negativity and suffering.`, ja: `このシンプルだが強力なマントラは、伝統的に否定性と苦しみを取り除くと信じられています。` } },
      { type: "paragraph", text: { en: `An even more powerful option is the Maha Mrityunjaya Mantra, although it requires greater effort to learn correctly.`, ja: `さらに強力なオプションはマハ ムリティウンジャヤ マントラですが、正しく学ぶには多大な努力が必要です。` } },
      { type: "paragraph", text: { en: `Why are these mantras considered so effective? It is often said that "Shiva sits above all the planets" [5]. In essence, this means that Shiva Tattva—Shiva Consciousness—has the power to transcend and override the planetary influences shown in a birth chart. Chanting Shiva mantras helps enliven this higher consciousness within our awareness [6].`, ja: `なぜこれらのマントラは非常に効果的だと考えられているのでしょうか？ 「シヴァはすべての惑星の上に座している」とよく言われます [5]。本質的に、これは、シヴァ タットヴァ、つまりシヴァ意識が、出生図に示されている惑星の影響を超越して無効にする力を持っていることを意味します。シヴァのマントラを唱えることは、私たちの意識の中でこの高次の意識を活性化するのに役立ちます[6]。` } },
    ],
  },
  {
    id: "charity",
    section: "remedies",
    title: { en: `Acts of Charity to Balance Planetary Energies`, ja: `惑星のエネルギーのバランスをとるための慈善活動` },
    related: ["planetary-antidotes","vedic-rituals","jyotish-and-karma"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Acts of Charity to Balance Planetary Energies`, ja: `惑星のエネルギーのバランスをとるための慈善活動` } },
      { type: "paragraph", text: { en: `Because the Vedic tradition sees all existence as interconnected, specific acts of charity are believed to reduce karmas associated with particular planets.`, ja: `ヴェーダの伝統ではすべての存在は相互につながっていると考えられているため、特定の慈善行為は特定の惑星に関連するカルマを軽減すると信じられています。` } },
      { type: "paragraph", text: { en: `Even if one views these ideas symbolically, giving a portion of one's income to worthwhile causes remains beneficial. A living enlightened Vedic Saint encourages everyone to donate a small percentage of their income, explaining that doing so may reduce the likelihood of disputes, legal difficulties, and related challenges.`, ja: `たとえこれらの考えを象徴的に捉えていたとしても、収入の一部を価値ある活動に寄付することは有益であることに変わりはありません。生きている啓発されたヴェーダの聖者は、収入のわずかな割合を寄付することをすべての人に奨励し、そうすることで紛争、法的問題、および関連する問題の可能性が減る可能性があると説明しています。` } },
      { type: "paragraph", text: { en: `Some remedies are surprisingly simple. For example, feeding crows on a Saturday is traditionally believed to alleviate certain karmic burdens connected with Saturn.`, ja: `いくつかの治療法は驚くほど簡単です。たとえば、土曜日にカラスに餌をあげると、土星に関係する特定のカルマの重荷が軽減されると伝統的に信じられています。` } },
      { type: "paragraph", text: { en: `Since different planets are linked to specific days of the week, charitable acts are often performed on the day associated with the relevant planet.`, ja: `さまざまな惑星が特定の曜日に関連付けられているため、慈善活動は関連する惑星に関連付けられた日に行われることがよくあります。` } },
      { type: "paragraph", text: { en: `Although some may regard these practices as superstitious, they have endured across generations. Modern scientific interest in interconnected systems provides additional support for concepts long recognised by the ancient Vedic sages.`, ja: `これらの習慣は迷信だと考える人もいるかもしれませんが、世代を超えて受け継がれてきました。相互接続されたシステムに対する現代の科学的関心は、古代ヴェーダの賢人によって長年認識されてきた概念をさらに裏付けるものとなっています。` } },
    ],
  },
  {
    id: "vedic-rituals",
    section: "remedies",
    title: { en: `Conducting Vedic Rituals to Remove Negativity`, ja: `否定的なものを取り除くためのヴェーダ儀式の実施` },
    related: ["mantras","charity","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Conducting Vedic Rituals to Remove Negativity`, ja: `否定的なものを取り除くためのヴェーダ儀式の実施` } },
      eduImage(educationImages.vedicRituals, {
        en: "Conducting Vedic rituals to remove negativity",
        ja: "否定的なエネルギーを取り除くヴェーダ儀式",
      }),
      { type: "paragraph", text: { en: `Since ancient times, Vedic rituals have been used to harmonise and manage the forces of nature. Traditional ceremonies known as Yagnas, Yajnas, or Yagyas were believed to bring timely rainfall, healthy crops, and prosperity.`, ja: `古代以来、ヴェーダの儀式は自然の力を調和させ、管理するために使用されてきました。ヤグナス、ヤグナ、またはヤギャとして知られる伝統的な儀式は、適時の降雨、健全な作物、繁栄をもたらすと信じられていました。` } },
      { type: "paragraph", text: { en: `In a similar way, difficulties caused by imbalanced planetary energies in a birth chart can be addressed through these sacred rituals.`, ja: `同様に、出生図における惑星エネルギーの不均衡によって引き起こされる困難も、これらの神聖な儀式を通じて対処することができます。` } },
      { type: "paragraph", text: { en: `Some may interpret these ceremonies as "planet worship," but their purpose is much more subtle and profound. They may be better understood as a form of karmic engineering designed to modify returning karmas and reduce suffering.`, ja: `これらの儀式を「惑星崇拝」と解釈する人もいるかもしれませんが、その目的はもっと微妙で奥深いものです。それらは、戻ってくるカルマを修正し、苦しみを軽減するために設計されたカルマ工学の一形態としてよりよく理解されるかもしれません。` } },
      { type: "paragraph", text: { en: `The procedures for conducting these rituals were traditionally regarded as Divine knowledge given for the benefit of humanity.`, ja: `これらの儀式を行う手順は伝統的に、人類の利益のために与えられた神の知識とみなされてきました。` } },
      { type: "paragraph", text: { en: `When performed correctly, with the appropriate Vedic mantras and procedures, these ceremonies bring Graha Shanti—peace from the planets. They are ideally performed by highly trained pundits with elevated levels of consciousness.`, ja: `適切なヴェーダのマントラと手順に従って正しく行われた場合、これらの儀式はグラハ シャンティ、つまり惑星からの平和をもたらします。これらは、意識レベルを高めた、高度に訓練された専門家によって実行されるのが理想的です。` } },
      { type: "paragraph", text: { en: `Their effectiveness is generally considered greatest when conducted in an Ashram or Temple according to traditional guidelines and with all required ingredients. They may be especially powerful when performed under the guidance of an enlightened Guru.`, ja: `一般に、その効果は、アシュラムまたは寺院で伝統的なガイドラインに従って、必要な材料をすべて使用して行われた場合に最大であると考えられています。啓発されたグルの指導の下で実行されると、特に強力になる可能性があります。` } },
      { type: "paragraph", text: { en: `These rituals can target the effects of a single problematic planet or, when necessary, address all nine planetary energies simultaneously to create balance, harmony, and peace throughout the chart.`, ja: `これらの儀式は、問題のある単一の惑星の影響をターゲットにすることも、必要に応じて、9 つの惑星のエネルギーすべてに同時に対処して、チャート全体のバランス、調和、平和を生み出すこともできます。` } },
    ],
  }
];
